insert into public.tree_planting_specs_i18n (slug,lang,care_notes,swiss_notes,toxicity_note,pruning_window,verified) values
('abies_alba','en','Roots more deeply and is more storm-resistant than spruce (heart-root system), shade-tolerant when young. Strongly threatened by browsing from roe deer/chamois — protection required.','Important mixed-forest tree species, more climate-resilient than spruce thanks to its taproot/heart-root. Browsing by hoofed game is the main problem for natural regeneration.',NULL,'rarely necessary; if so, in late summer','f'),
('abies_alba','es','Enraíza más profundamente y resiste mejor el viento que la pícea (sistema de raíz en corazón), tolerante a la sombra de joven. Muy amenazado por el ramoneo de corzos/rebecos — se requiere protección.','Especie importante del bosque mixto, más resiliente al clima que la pícea gracias a su raíz pivotante/en corazón. El ramoneo por ungulados es el principal problema de la regeneración natural.',NULL,'rara vez necesaria; en su caso, a finales de verano','f'),
('abies_alba','fr','Enracinement plus profond et meilleure résistance au vent que l''épicéa (système à racines obliques/pivot), tolérant à l''ombre dans sa jeunesse. Fortement menacé par l''abroutissement du chevreuil/chamois — protection nécessaire.','Essence importante des forêts mixtes, plus résiliente au climat que l''épicéa grâce à sa racine pivotante/oblique. L''abroutissement par le gibier à onglons est le principal problème de la régénération naturelle.',NULL,'rarement nécessaire ; le cas échéant en fin d''été','f'),
('abies_alba','it','Radica più in profondità ed è più resistente al vento dell''abete rosso (sistema a radici oblique/fittone), tollerante all''ombra in gioventù. Fortemente minacciato dal brucamento di caprioli/camosci — protezione necessaria.','Importante specie del bosco misto, più resiliente al clima dell''abete rosso grazie alla radice a fittone/obliqua. Il brucamento da parte degli ungulati è il problema principale della rinnovazione naturale.',NULL,'raramente necessario; eventualmente a fine estate','f'),
('acer_campestre','en','Native, ecologically valuable (bee forage, bird food). Non-toxic. Very tolerant of pruning, ideal for a near-natural clipped hedge. Note: the leaves of sycamore maple (A. pseudoplatanus) are problematic for horses — field maple is considered uncritical, non-toxic for humans and pets.','Native to the Central Plateau and Jura, a popular species for wild/low hedges, promotes biodiversity.',NULL,'June-July and February (not during the spring sap flow — bleeds)','f'),
('acer_campestre','es','Autóctono, ecológicamente valioso (pasto para abejas, alimento para aves). No tóxico. Muy tolerante a la poda, ideal para un seto recortado seminatural. Nota: las hojas del arce sicómoro (A. pseudoplatanus) son problemáticas para los caballos — el arce menor se considera no crítico, no tóxico para humanos y mascotas.','Autóctono en la Meseta Central y el Jura, especie apreciada para setos silvestres/bajos, fomenta la biodiversidad.',NULL,'junio-julio y febrero (no durante la subida de savia en primavera — sangra)','f'),
('acer_campestre','fr','Indigène, écologiquement précieux (pâture à abeilles, nourriture pour oiseaux). Non toxique. Très tolérant à la taille, idéal pour une haie taillée proche de la nature. Remarque : les feuilles de l''érable sycomore (A. pseudoplatanus) sont problématiques pour les chevaux — l''érable champêtre est considéré comme non critique, non toxique pour l''homme et les animaux domestiques.','Indigène sur le Plateau et dans le Jura, espèce appréciée des haies sauvages/basses, favorise la biodiversité.',NULL,'juin-juillet et février (pas pendant la montée de sève au printemps — saigne)','f'),
('acer_campestre','it','Indigeno, ecologicamente prezioso (pascolo per api, nutrimento per uccelli). Non tossico. Molto tollerante alla potatura, ideale per una siepe potata seminaturale. Nota: le foglie dell''acero di monte (A. pseudoplatanus) sono problematiche per i cavalli — l''acero campestre è considerato non critico, non tossico per l''uomo e gli animali domestici.','Indigeno sull''Altopiano e nel Giura, specie apprezzata per siepi selvatiche/basse, favorisce la biodiversità.',NULL,'giugno-luglio e febbraio (non durante la risalita della linfa in primavera — sanguina)','f'),
('acer_palmatum','en','Note: Acer species (especially A. rubrum/red maple) are toxic to horses (wilted leaves); A. palmatum is considered non-toxic to dogs/cats/humans. Sensitive to sunburn and drought — mulch, keep evenly moist. Prune sparingly, risk of bleeding during sap flow.','In CH a common solitary and container tree; non-toxic to humans/dogs/cats. Horse owners: as a rule, do not feed any Acer leaves.',NULL,'late summer to early autumn (Aug-Sept); NOT in spring (heavy bleeding/sap pressure)','f'),
('acer_palmatum','es','Nota: las especies de Acer (sobre todo A. rubrum/arce rojo) son tóxicas para los caballos (hojas marchitas); A. palmatum se considera no tóxico para perros/gatos/humanos. Sensible a las quemaduras solares y a la sequía — acolchar, mantener una humedad uniforme. Podar con moderación, riesgo de sangrado durante la subida de savia.','En CH es un árbol solitario y de maceta frecuente; no tóxico para humanos/perros/gatos. Propietarios de caballos: por norma, no dar de comer hojas de Acer.',NULL,'de finales de verano a principios de otoño (ago-sept); NO en primavera (fuerte flujo/presión de savia)','f'),
('acer_palmatum','fr','Remarque : les espèces d''Acer (surtout A. rubrum/érable rouge) sont toxiques pour les chevaux (feuilles fanées) ; A. palmatum est considéré comme non toxique pour les chiens/chats/humains. Sensible aux coups de soleil et à la sécheresse — pailler, maintenir une humidité régulière. Taille parcimonieuse, risque de saignement pendant la montée de sève.','En CH, arbre solitaire et de bac fréquent ; non toxique pour l''homme/le chien/le chat. Détenteurs de chevaux : en général ne pas donner de feuilles d''Acer à brouter.',NULL,'de la fin de l''été au début de l''automne (août-sept) ; PAS au printemps (fort écoulement de sève/pression de sève)','f'),
('acer_palmatum','it','Nota: le specie di Acer (soprattutto A. rubrum/acero rosso) sono tossiche per i cavalli (foglie appassite); A. palmatum è considerato non tossico per cani/gatti/uomo. Sensibile alle scottature solari e alla siccità — pacciamare, mantenere un''umidità costante. Potatura parsimoniosa, rischio di sanguinamento durante la risalita della linfa.','In CH frequente albero solitario e da vaso; non tossico per uomo/cane/gatto. Detentori di cavalli: in generale non somministrare foglie di Acer.',NULL,'dalla fine dell''estate all''inizio dell''autunno (ago-set); NON in primavera (forte flusso di linfa/pressione della linfa)','f'),
('acer_platanoides','en','Classified as non-toxic to humans and animals by tox.ch / specialist sources (unlike the closely related sycamore maple — no relevant hypoglycin-A pasture myopathy documented). Important early bee forage. Strong, shallow-spreading root pressure — can lift paving, maintain a minimum distance. Self-seeds vigorously.','In Switzerland a widespread urban and park tree up to ~1300 m. Mind root pressure near paths/paving. Non-toxic — child-safe.',NULL,'summer or autumn after leaf fall; NOT in spring (strong sap flow/bleeding)','f'),
('acer_platanoides','es','Clasificado como no tóxico para humanos y animales por tox.ch / fuentes especializadas (a diferencia del arce sicómoro emparentado — no hay miopatía de pastoreo por hipoglicina A documentada). Importante pasto temprano para abejas. Fuerte presión radicular superficial y extendida — puede levantar los pavimentos, mantener una distancia mínima. Se resiembra abundantemente.','En Suiza, árbol urbano y de parque extendido hasta ~1300 m. Tener en cuenta la presión radicular cerca de caminos/pavimentos. No tóxico — seguro para niños.',NULL,'verano u otoño tras la caída de la hoja; NO en primavera (fuerte subida de savia/sangrado)','f'),
('acer_platanoides','fr','Classé non toxique pour l''homme et l''animal par tox.ch / sources spécialisées (contrairement à l''érable sycomore proche — aucune myopathie de pâture liée à l''hypoglycine A documentée). Importante pâture précoce à abeilles. Forte pression racinaire superficielle et étalée — peut soulever les revêtements, respecter une distance minimale. Se ressème abondamment.','En Suisse, arbre de ville et de parc répandu jusqu''à ~1300 m. Tenir compte de la pression racinaire près des chemins/revêtements. Non toxique — sûr pour les enfants.',NULL,'été ou automne après la chute des feuilles ; PAS au printemps (forte montée de sève/saignement)','f'),
('acer_platanoides','it','Classificato come non tossico per l''uomo e gli animali da tox.ch / fonti specializzate (a differenza del vicino acero di monte — nessuna miopatia da pascolo legata all''ipoglicina A documentata). Importante pascolo precoce per api. Forte pressione radicale superficiale ed estesa — può sollevare le pavimentazioni, rispettare una distanza minima. Si dissemina abbondantemente.','In Svizzera albero cittadino e da parco diffuso fino a ~1300 m. Tenere conto della pressione radicale presso sentieri/pavimentazioni. Non tossico — sicuro per i bambini.',NULL,'estate o autunno dopo la caduta delle foglie; NON in primavera (forte flusso di linfa/sanguinamento)','f'),
('acer_pseudoplatanus','en','Seeds and seedlings contain hypoglycin A — causes the fatal atypical pasture myopathy in horses. Do NOT plant near horse pastures; fallen seeds can be blown several hundred metres by the wind. Fast-growing, strong root pressure — maintain a minimum distance from buildings/utility lines.','In Switzerland the most frequent maple species, up to 1700 m (mountain forests). Caution for horse keeping: sycamore maple seeds = main cause of atypical pasture myopathy (76% of cases Oct-Dec). Heed the tox.ch / veterinary clinic warning.','Seeds and seedlings (hypoglycin A); leaves largely non-toxic','summer (July/August) or autumn after leaf fall; NOT in spring (bleeding pressure/sap flow)','f'),
('acer_pseudoplatanus','es','Las semillas y las plántulas contienen hipoglicina A — provoca en el caballo la miopatía atípica del pastoreo, mortal. NO plantar cerca de pastos para caballos; las semillas caídas pueden ser arrastradas por el viento varios cientos de metros. De crecimiento rápido, fuerte presión radicular — mantener una distancia mínima a edificios/conducciones.','En Suiza es la especie de arce más frecuente, hasta 1700 m (bosques de montaña). Atención para la tenencia de caballos: las semillas del arce sicómoro = causa principal de la miopatía atípica del pastoreo (76% de los casos oct-dic). Tener en cuenta la advertencia de tox.ch / clínica veterinaria.','Semillas y plántulas (hipoglicina A); hojas en gran parte no tóxicas','verano (julio/agosto) u otoño tras la caída de la hoja; NO en primavera (presión de sangrado/flujo de savia)','f'),
('acer_pseudoplatanus','fr','Les graines et les semis contiennent de l''hypoglycine A — cause chez le cheval la myopathie atypique des pâturages, mortelle. NE PAS planter à proximité de pâtures à chevaux ; les graines tombées peuvent être emportées par le vent sur plusieurs centaines de mètres. À croissance rapide, forte pression racinaire — respecter une distance minimale aux bâtiments/conduites.','En Suisse, l''espèce d''érable la plus fréquente, jusqu''à 1700 m (forêts de montagne). Attention détention de chevaux : les graines d''érable sycomore = cause principale de la myopathie atypique des pâturages (76% des cas oct-déc). Tenir compte de l''avertissement tox.ch / clinique vétérinaire.','Graines et semis (hypoglycine A) ; feuilles en grande partie non toxiques','été (juillet/août) ou automne après la chute des feuilles ; PAS au printemps (pression de saignement/montée de sève)','f'),
('acer_pseudoplatanus','it','I semi e le piantine contengono ipoglicina A — provoca nel cavallo la miopatia atipica da pascolo, mortale. NON piantare vicino a pascoli per cavalli; i semi caduti possono essere trasportati dal vento per diverse centinaia di metri. A crescita rapida, forte pressione radicale — rispettare una distanza minima da edifici/condutture.','In Svizzera la specie di acero più frequente, fino a 1700 m (boschi di montagna). Attenzione per la detenzione di cavalli: i semi dell''acero di monte = causa principale della miopatia atipica da pascolo (76% dei casi ott-dic). Tenere conto dell''avvertenza di tox.ch / clinica veterinaria.','Semi e piantine (ipoglicina A); foglie in gran parte non tossiche','estate (luglio/agosto) o autunno dopo la caduta delle foglie; NON in primavera (pressione di sanguinamento/flusso di linfa)','f'),
('aesculus_hippocastanum','en','Correction: downgraded from ''strongly'' to ''slightly'' — tox.ch/CliniTox classify the horse chestnut as weakly/slightly toxic (aescin, aesculin). In children, ~5 swallowed seeds can trigger vomiting/diarrhoea/visual disturbances; in dogs, vomiting/colic. Do not eat (confusion with the edible sweet chestnut Castanea sativa!). child_pet_safe remains false, as it is symptomatically toxic if eaten.','In Switzerland a typical park, avenue and beer-garden tree. Massively attacked by the leaf miner. Risk of confusing the seeds with the edible sweet chestnut — important safety information for the app. Poison emergency CH 145.','Seeds (conkers), unripe fruit, husk and young shoots (aescin/aesculin)','winter (leafless) or high summer; tolerates pruning moderately','f'),
('aesculus_hippocastanum','es','Corrección: reclasificado de «fuertemente» a «ligeramente» — tox.ch/CliniTox clasifican el castaño de Indias como débilmente/ligeramente tóxico (aescina, esculina). En niños, ~5 semillas tragadas pueden provocar vómitos/diarrea/trastornos visuales; en perros, vómitos/cólicos. No consumir (¡confusión con la castaña comestible Castanea sativa!). child_pet_safe permanece false, ya que es sintomáticamente tóxico si se ingiere.','En Suiza, árbol típico de parques, avenidas y cervecerías al aire libre. Masivamente atacado por la polilla minadora. Riesgo de confundir las semillas con la castaña comestible — información de seguridad importante para la app. Urgencia toxicológica CH 145.','Semillas (castañas de Indias), frutos inmaduros, cáscara y brotes jóvenes (aescina/esculina)','invierno (sin hojas) o pleno verano; tolera la poda moderadamente','f'),
('aesculus_hippocastanum','fr','Correction : reclassé de « fortement » à « légèrement » — tox.ch/CliniTox classent le marronnier d''Inde comme faiblement/légèrement toxique (aescine, esculine). Chez l''enfant, ~5 graines avalées peuvent provoquer vomissements/diarrhée/troubles visuels ; chez le chien, vomissements/coliques. Ne pas consommer (confusion avec la châtaigne comestible Castanea sativa !). child_pet_safe reste false, car symptomatiquement toxique en cas d''ingestion.','En Suisse, arbre typique des parcs, allées et jardins de bière. Massivement attaqué par la mineuse du marronnier. Risque de confusion des graines avec la châtaigne comestible — information de sécurité importante pour l''app. Urgence toxicologique CH 145.','Graines (marrons), fruits non mûrs, écorce et jeunes pousses (aescine/esculine)','hiver (sans feuilles) ou plein été ; supporte modérément la taille','f'),
('aesculus_hippocastanum','it','Correzione: riclassificato da «fortemente» a «leggermente» — tox.ch/CliniTox classificano l''ippocastano come debolmente/leggermente tossico (escina, esculina). Nei bambini, ~5 semi ingeriti possono provocare vomito/diarrea/disturbi visivi; nei cani, vomito/coliche. Non consumare (confusione con la castagna commestibile Castanea sativa!). child_pet_safe resta false, poiché sintomaticamente tossico in caso di ingestione.','In Svizzera tipico albero di parchi, viali e birrerie all''aperto. Massicciamente colpito dalla minatrice fogliare dell''ippocastano. Rischio di confusione dei semi con la castagna commestibile — informazione di sicurezza importante per l''app. Emergenza tossicologica CH 145.','Semi (castagne d''India), frutti acerbi, scorza e giovani getti (escina/esculina)','inverno (senza foglie) o piena estate; sopporta moderatamente la potatura','f'),
('amelanchier_lamarckii','en','Value-adding garden tree: white bloom in April, edible sweet blue-black berries in June (eaten raw, loved by birds), brilliant orange-red autumn colour. Undemanding, adaptable. Suitable for small gardens. Berries non-toxic and edible.','Popular, robust small tree/large shrub for CH gardens up to about 1200 m. Bird-feeding shrub, very bee-friendly early bloom. Low-maintenance garden tree for small plots.',NULL,'after flowering (late spring) or in winter, little pruning needed','f'),
('amelanchier_lamarckii','es','Árbol de jardín con valor añadido: floración blanca en abril, bayas azul-negras dulces comestibles en junio (se comen crudas, apreciadas por las aves), colorido otoñal intenso naranja-rojo. Poco exigente, adaptable. Apto para jardines pequeños. Bayas no tóxicas y comestibles.','Pequeño árbol/gran arbusto robusto y apreciado para los jardines de CH hasta aprox. 1200 m. Arbusto nutricio para aves, floración temprana muy favorable a las abejas. Árbol de jardín de fácil cuidado para parcelas pequeñas.',NULL,'tras la floración (final de primavera) o en invierno, poca poda necesaria','f'),
('amelanchier_lamarckii','fr','Arbre d''agrément à valeur ajoutée : floraison blanche en avril, baies bleu-noir sucrées comestibles en juin (à croquer crues, appréciées des oiseaux), coloration automnale éclatante orange-rouge. Peu exigeant, adaptable. Convient aux petits jardins. Baies non toxiques et comestibles.','Petit arbre/grand arbuste robuste et apprécié pour les jardins CH jusqu''à env. 1200 m. Arbuste nourricier pour oiseaux, floraison précoce très favorable aux abeilles. Arbre d''agrément facile d''entretien pour les petits terrains.',NULL,'après la floraison (fin du printemps) ou en hiver, peu de taille nécessaire','f'),
('amelanchier_lamarckii','it','Albero da giardino di valore aggiunto: fioritura bianca in aprile, bacche blu-nere dolci commestibili in giugno (da mangiare crude, gradite agli uccelli), colorazione autunnale brillante arancio-rossa. Poco esigente, adattabile. Adatto a piccoli giardini. Bacche non tossiche e commestibili.','Piccolo albero/grande arbusto robusto e apprezzato per i giardini CH fino a circa 1200 m. Arbusto nutritivo per uccelli, fioritura precoce molto favorevole alle api. Albero da giardino facile da curare per piccoli terreni.',NULL,'dopo la fioritura (tarda primavera) o in inverno, poca potatura necessaria','f'),
('aronia_melanocarpa','en','Very robust, frost-hardy and undemanding, also as a wild shrub/hedge. Berries raw are tart-astringent, mostly processed (juice, jam) — very rich in anthocyanins. The amygdalin in the seeds breaks down on heating; toxicologically relevant only with extremely high raw consumption (several kg), therefore safe as food. ''Slight'' rating is conservative because of the cyanogenic glycoside in the seed.','In CH popular as a low-maintenance, very hardy berry and bird-feeding shrub; up to ~1500 m. Flesh harmless for children/pets; in normal household amounts no cyanide hazard (Max Rubner Institute, gartenjournal.net). ''Slight'' = cautious rating because of the amygdalin in the seed.','Seeds/kernels contain traces of amygdalin (cyanogenic glycoside); the flesh is harmless','late winter (rejuvenation/thinning pruning)','f'),
('aronia_melanocarpa','es','Muy robusta, resistente a las heladas y poco exigente, también como arbusto silvestre/seto. Las bayas crudas son ásperas-astringentes, en su mayoría procesadas (zumo, mermelada) — muy ricas en antocianinas. La amigdalina de las semillas se descompone al calentar; toxicológicamente relevante solo con un consumo crudo extremadamente alto (varios kg), por lo que es segura como alimento. La clasificación «leve» es conservadora por el glucósido cianogénico de la semilla.','En CH es apreciada como arbusto de bayas y nutricio para aves, de fácil cuidado y muy resistente; hasta ~1500 m. La pulpa es inofensiva para niños/mascotas; en cantidades domésticas habituales no hay peligro de cianuro (Instituto Max Rubner, gartenjournal.net). «Leve» = clasificación prudente por la amigdalina de la semilla.','Las semillas/huesos contienen trazas de amigdalina (glucósido cianogénico); la pulpa es inofensiva','finales de invierno (poda de rejuvenecimiento/aclareo)','f'),
('aronia_melanocarpa','fr','Très robuste, rustique et peu exigeant, aussi comme arbuste sauvage/haie. Baies crues âpres-astringentes, le plus souvent transformées (jus, confiture) — très riches en anthocyanes. L''amygdaline des pépins se dégrade à la cuisson ; toxicologiquement pertinente seulement en cas de consommation crue extrêmement élevée (plusieurs kg), donc sûre comme aliment. Classement « léger » prudent en raison du glycoside cyanogène dans la graine.','En CH, apprécié comme arbuste à baies et nourricier pour oiseaux, facile d''entretien et très rustique ; jusqu''à ~1500 m. Pulpe inoffensive pour enfants/animaux domestiques ; en quantités ménagères usuelles aucun danger de cyanure (Institut Max Rubner, gartenjournal.net). « Léger » = classement prudent en raison de l''amygdaline dans le pépin.','Les graines/pépins contiennent des traces d''amygdaline (glycoside cyanogène) ; la pulpe est inoffensive','fin de l''hiver (taille de rajeunissement/d''éclaircie)','f'),
('aronia_melanocarpa','it','Molto robusta, rustica e poco esigente, anche come arbusto selvatico/siepe. Bacche crude aspre-astringenti, per lo più trasformate (succo, marmellata) — molto ricche di antociani. L''amigdalina nei semi si degrada con la cottura; tossicologicamente rilevante solo in caso di consumo crudo estremamente elevato (diversi kg), quindi sicura come alimento. Classificazione «lieve» prudente a causa del glicoside cianogeno nel seme.','In CH apprezzata come arbusto da bacche e nutritivo per uccelli, facile da curare e molto rustico; fino a ~1500 m. Polpa innocua per bambini/animali domestici; in quantità domestiche usuali nessun pericolo di cianuro (Istituto Max Rubner, gartenjournal.net). «Lieve» = classificazione prudente a causa dell''amigdalina nel seme.','I semi/noccioli contengono tracce di amigdalina (glicoside cianogeno); la polpa è innocua','fine inverno (potatura di ringiovanimento/diradamento)','f'),
('betula_pendula','en','Non-toxic, but a strong pollen allergen — not ideal for allergy households. Shallow roots with high water demand: can cause problems near buildings/utility lines and lift paving. Fast-growing, short-lived pioneer species. Hardy down to -40 °C.','Native pioneer species, up to ~2000 m (subalpine). In Switzerland the main cause of spring pollen allergy. Shallow-rooting — keep distance from drainage/foundations.',NULL,'summer/autumn (August-October); NOT in spring/late winter (heavy bleeding)','f'),
('betula_pendula','es','No tóxico, pero fuerte alérgeno polínico — no ideal para hogares de alérgicos. Raíces superficiales con alta demanda de agua: puede causar problemas cerca de edificios/conducciones y levantar los pavimentos. Especie pionera de crecimiento rápido y vida corta. Resistente hasta -40 °C.','Especie pionera autóctona, hasta ~2000 m (subalpino). En Suiza, principal causa de alergia al polen primaveral. Raíces superficiales — mantener distancia a drenajes/cimientos.',NULL,'verano/otoño (agosto-octubre); NO en primavera/finales de invierno (fuerte sangrado)','f'),
('betula_pendula','fr','Non toxique, mais fort allergène pollinique — pas idéal pour les foyers d''allergiques. Racines superficielles à fort besoin en eau : peut poser problème près des bâtiments/conduites et soulever les revêtements. Espèce pionnière à croissance rapide et courte durée de vie. Rustique jusqu''à -40 °C.','Espèce pionnière indigène, jusqu''à ~2000 m (subalpin). En Suisse, principale cause d''allergie au pollen de printemps. Racines superficielles — respecter une distance aux drainages/fondations.',NULL,'été/automne (août-octobre) ; PAS au printemps/fin de l''hiver (forts saignements)','f'),
('betula_pendula','it','Non tossica, ma forte allergene pollinico — non ideale per le case di allergici. Radici superficiali con elevato fabbisogno idrico: può creare problemi presso edifici/condutture e sollevare le pavimentazioni. Specie pioniera a crescita rapida e di breve durata. Rustica fino a -40 °C.','Specie pioniera indigena, fino a ~2000 m (subalpino). In Svizzera, causa principale dell''allergia ai pollini primaverili. Radici superficiali — rispettare una distanza da drenaggi/fondamenta.',NULL,'estate/autunno (agosto-ottobre); NON in primavera/fine inverno (forte sanguinamento)','f'),
('carpinus_betulus','en','Classic clipped hedge, holds its dry foliage in winter (wind/privacy screen). Non-toxic. Very tolerant of pruning, withstands cutting back into old wood.','Native, widespread throughout Switzerland up to the montane belt. The most popular deciduous hedge alongside beech.',NULL,'June-July and February','f'),
('carpinus_betulus','es','Seto recortado clásico, conserva el follaje seco en invierno (cortavientos/pantalla). No tóxico. Muy tolerante a la poda, soporta el corte sobre madera vieja.','Autóctono, extendido por toda Suiza hasta el piso montano. El seto de hoja caduca más apreciado junto al haya.',NULL,'junio-julio y febrero','f'),
('carpinus_betulus','fr','Haie taillée classique, conserve le feuillage sec en hiver (brise-vent/écran). Non toxique. Très tolérant à la taille, supporte un rabattage sur le vieux bois.','Indigène, répandu dans toute la Suisse jusqu''à l''étage montagnard. La haie de feuillus la plus appréciée après le hêtre.',NULL,'juin-juillet et février','f'),
('carpinus_betulus','it','Siepe potata classica, mantiene il fogliame secco in inverno (frangivento/schermo). Non tossico. Molto tollerante alla potatura, sopporta il taglio sul legno vecchio.','Indigeno, diffuso in tutta la Svizzera fino al piano montano. La siepe di latifoglie più apprezzata dopo il faggio.',NULL,'giugno-luglio e febbraio','f'),
('castanea_sativa','en','Needs lime-free, acidic, well-drained soil – tolerates neither waterlogging nor lime. Cross-pollination required (second clone/seedling). Massive mature tree, allow a generous site. Sweet chestnut (marron) edible after roasting/cooking.','Iconic tree of Ticino and southern Switzerland (chestnut groves "selve"). Widespread in Valais and on the shores of Lake Geneva. Prefers mild, lime-free sites up to about 1000 m. Marroni tradition.',NULL,'Winter (February) to early spring, before bud break','f'),
('castanea_sativa','es','Necesita suelo ácido, sin cal y con buen drenaje – no tolera el encharcamiento ni la cal. Requiere polinización cruzada (segundo clon/plántula). Árbol de gran porte, prever un emplazamiento amplio. Castaña (marrón) comestible tras asarla/cocerla.','Árbol emblemático del Tesino y del sur de Suiza (castañares «selve»). Extendido en el Valais y a orillas del lago Lemán. Prefiere situaciones suaves y sin cal hasta unos 1000 m. Tradición de los marroni.',NULL,'Invierno (febrero) hasta inicio de primavera, antes de la brotación','f'),
('castanea_sativa','fr','Exige un sol acide, sans calcaire et drainant – ne supporte ni l''eau stagnante ni le calcaire. Pollinisation croisée nécessaire (second clone/semis). Arbre de grande envergure, prévoir un emplacement généreux. Châtaigne (marron) comestible après rôtissage/cuisson.','Arbre emblématique du Tessin et du sud de la Suisse (châtaigneraies « selve »). Répandu en Valais et sur les rives du Léman. Préfère les situations douces et sans calcaire jusqu''à env. 1000 m. Tradition des marrons.',NULL,'Hiver (février) à début du printemps, avant le débourrement','f'),
('castanea_sativa','it','Richiede terreno acido, privo di calcare e drenante – non tollera ristagni idrici né calcare. Necessaria impollinazione incrociata (secondo clone/semenzale). Albero imponente, prevedere uno spazio ampio. Castagna (marrone) commestibile dopo arrostitura/cottura.','Albero simbolo del Ticino e della Svizzera meridionale (selve castanili). Diffuso in Vallese e sulle rive del Lemano. Predilige posizioni miti e prive di calcare fino a ca. 1000 m. Tradizione dei marroni.',NULL,'Inverno (febbraio) fino a inizio primavera, prima del germogliamento','f'),
('catalpa_bignonioides_nana','en','The grafted ball form "Nana" usually does not flower and forms hardly any pods. Very large foliage – place sheltered from wind. Roots and pods/seeds considered toxic (GI/CNS irritation), foliage contact may irritate the skin. Annual pruning for a compact ball.','In CH a popular ball tree for small and front gardens. CORRECTED/CLARIFIED: tox.ch and PFAF confirm toxicity (roots strongly, pods/seeds moderately) – "mild" kept as a conservative lower bound, child_pet_safe=false correct (do NOT set to true).','Roots (PFAF: "highly poisonous"), fruits/pods and seeds (GI/CNS irritation in larger amounts); foliage can cause skin irritation','Winter to early spring (leafless); cut the ball crown back to the branch collar annually','f'),
('catalpa_bignonioides_nana','es','La forma esférica injertada «Nana» por lo general no florece y apenas forma vainas. Follaje muy grande – ubicar al resguardo del viento. Raíces y vainas/semillas consideradas tóxicas (irritación gastrointestinal/SNC), el contacto con el follaje puede irritar la piel. Poda anual para una esfera compacta.','En CH, árbol esférico apreciado para jardines pequeños y antejardines. CORREGIDO/PRECISADO: tox.ch y PFAF confirman la toxicidad (raíces fuertemente, vainas/semillas moderadamente) – «leve» mantenida como límite inferior prudente, child_pet_safe=false correcto (NO poner en true).','Raíces (PFAF: «highly poisonous»), frutos/vainas y semillas (irritación gastrointestinal/SNC en cantidad mayor); el follaje puede provocar irritación cutánea','Invierno hasta inicio de primavera (sin hojas); recortar anualmente la copa esférica hasta el cuello de las ramas','f'),
('catalpa_bignonioides_nana','fr','La forme greffée en boule « Nana » ne fleurit généralement pas et ne forme guère de gousses. Feuillage très grand – installer à l''abri du vent. Racines et gousses/graines réputées toxiques (irritation gastro-intestinale/SNC), le contact du feuillage peut irriter la peau. Taille annuelle pour une boule compacte.','En CH, arbre boule prisé pour petits jardins et avant-jardins. CORRIGÉ/PRÉCISÉ : tox.ch et PFAF confirment la toxicité (racines fortement, gousses/graines modérément) – « légère » conservée comme borne inférieure prudente, child_pet_safe=false correct (NE PAS mettre à true).','Racines (PFAF : « highly poisonous »), fruits/gousses et graines (irritation gastro-intestinale/SNC en quantité importante) ; le feuillage peut provoquer une irritation cutanée','Hiver à début du printemps (sans feuilles) ; rabattre annuellement la couronne en boule sur l''empattement des branches','f'),
('catalpa_bignonioides_nana','it','La forma innestata a sfera « Nana » di norma non fiorisce e produce poche silique. Fogliame molto grande – collocare al riparo dal vento. Radici e silique/semi considerati tossici (irritazione gastrointestinale/SNC), il contatto con il fogliame può irritare la pelle. Potatura annuale per una sfera compatta.','In CH apprezzato albero a sfera per piccoli giardini e giardini d''ingresso. CORRETTO/PRECISATO: tox.ch e PFAF confermano la tossicità (radici forte, silique/semi moderata) – « lieve » mantenuta come limite inferiore prudente, child_pet_safe=false corretto (NON impostare su true).','Radici (PFAF: « highly poisonous »), frutti/silique e semi (irritazione gastrointestinale/SNC in quantità maggiore); il fogliame può causare irritazione cutanea','Inverno fino a inizio primavera (senza foglie); rimontare annualmente la chioma a sfera sul collare dei rami','f'),
('chamaecyparis_lawsoniana','en','Classed CONSERVATIVELY as strongly toxic (Cupressaceae terpenes as in Thuja, severe symptoms even from small ingested amounts, expert sources explicitly warn against planting near children/pets). The input data "mild" was inconsistent with safe=false – corrected to strong/child_pet_safe=false. Shallow-rooted, susceptible to Phytophthora root rot.','Popular hedge/specimen plant in gardens; ecologically poor and Phytophthora-prone. Prefer more nature-friendly native alternatives.','All parts of the plant (foliage, shoots, essential oil) contain irritant terpenes (incl. thujene, pinene). Ingestion of even small amounts can cause vomiting, diarrhoea, fever and dizziness; skin contact is irritating.','Spring to late summer (never cut into the old, leafless wood)','f'),
('chamaecyparis_lawsoniana','es','Clasificado de forma PRUDENTE como fuertemente tóxico (terpenos de las cupresáceas como en la tuya, síntomas graves ya con pequeñas cantidades ingeridas, las fuentes especializadas advierten explícitamente contra la plantación cerca de niños/mascotas). El dato de partida «leve» era incoherente con safe=false – corregido a fuerte/child_pet_safe=false. Enraizamiento superficial, sensible a la podredumbre radicular por Phytophthora.','Planta de seto/ejemplar aislado apreciada en jardines; ecológicamente pobre y propensa a Phytophthora. Preferir alternativas autóctonas más cercanas a la naturaleza.','Todas las partes de la planta (follaje, brotes, aceite esencial) contienen terpenos irritantes (entre otros tujeno, pineno). La ingestión de pequeñas cantidades puede provocar vómitos, diarrea, fiebre y mareos; el contacto cutáneo es irritante.','De primavera a finales de verano (nunca cortar en la madera vieja sin hojas)','f'),
('chamaecyparis_lawsoniana','fr','Classé PRUDEMMENT comme fortement toxique (terpènes des Cupressacées comme chez le thuya, symptômes graves dès de petites quantités ingérées, les sources spécialisées mettent explicitement en garde contre la plantation auprès d''enfants/animaux). La donnée d''entrée « légère » était incohérente avec safe=false – corrigée en forte/child_pet_safe=false. Enracinement superficiel, sensible à la pourriture racinaire à Phytophthora.','Plante de haie/sujet isolé prisée dans les jardins ; pauvre sur le plan écologique et sensible au Phytophthora. Privilégier des alternatives indigènes plus proches de la nature.','Toutes les parties de la plante (feuillage, pousses, huile essentielle) contiennent des terpènes irritants (entre autres thujène, pinène). L''ingestion de petites quantités peut provoquer vomissements, diarrhée, fièvre et vertiges ; contact cutané irritant.','Du printemps à la fin de l''été (ne jamais tailler dans le vieux bois sans feuilles)','f'),
('chamaecyparis_lawsoniana','it','Classificato PRUDENTEMENTE come fortemente tossico (terpeni delle Cupressacee come nella tuia, sintomi gravi già con piccole quantità ingerite, le fonti specialistiche mettono esplicitamente in guardia dalla piantagione presso bambini/animali). Il dato di partenza « lieve » era incoerente con safe=false – corretto in forte/child_pet_safe=false. Radici superficiali, soggetto a marciume radicale da Phytophthora.','Pianta da siepe/esemplare isolato apprezzata nei giardini; ecologicamente povera e soggetta a Phytophthora. Preferire alternative indigene più vicine alla natura.','Tutte le parti della pianta (fogliame, getti, olio essenziale) contengono terpeni irritanti (tra cui tujene, pinene). L''ingestione di piccole quantità può provocare vomito, diarrea, febbre e vertigini; contatto cutaneo irritante.','Dalla primavera alla fine dell''estate (mai potare nel vecchio legno privo di foglie)','f'),
('cornus_kousa_chinensis','en','Late and long flowering (creamy-white bracts), edible raspberry-like red aggregate fruits (non-toxic, slightly sweet). Lime-avoiding – acidic, humus-rich soil. More robust and more anthracnose-resistant than Cornus florida. Shallow-rooted – mulch, do not hoe.','In CH a popular, robust specimen ornamental tree; non-toxic, fruits edible – safe for children and pets. confirmed tox=none, safe=true.',NULL,'Pruning rarely needed; if required in late winter/early spring (leafless)','f'),
('cornus_kousa_chinensis','es','Floración tardía y prolongada (brácteas blanco crema), frutos compuestos rojos comestibles tipo frambuesa (no tóxicos, ligeramente dulces). Calcífugo – suelo ácido y rico en humus. Más robusto y más resistente a la antracnosis que Cornus florida. Enraizamiento superficial – acolchar, no escardar.','En CH, árbol ornamental aislado robusto y apreciado; no tóxico, frutos comestibles – seguro para niños y mascotas. confirmado tox=ninguna, safe=true.',NULL,'Poda raramente necesaria; si hace falta a finales de invierno/inicio de primavera (sin hojas)','f'),
('cornus_kousa_chinensis','fr','Floraison tardive et prolongée (bractées blanc crème), fruits composés rouges comestibles façon framboise (non toxiques, légèrement sucrés). Calcifuge – sol acide et humifère. Plus robuste et plus résistant à l''anthracnose que Cornus florida. Enracinement superficiel – pailler, ne pas biner.','En CH, arbre d''ornement isolé robuste et apprécié ; non toxique, fruits comestibles – sûr pour enfants et animaux. confirmé tox=aucune, safe=true.',NULL,'Taille rarement nécessaire ; si besoin en fin d''hiver/début de printemps (sans feuilles)','f'),
('cornus_kousa_chinensis','it','Fioritura tardiva e prolungata (brattee bianco crema), frutti composti rossi commestibili simili a lamponi (non tossici, leggermente dolci). Calcifugo – terreno acido e ricco di humus. Più robusto e più resistente all''antracnosi del Cornus florida. Radici superficiali – pacciamare, non zappare.','In CH apprezzato albero ornamentale isolato e robusto; non tossico, frutti commestibili – sicuro per bambini e animali. confermato tox=nessuna, safe=true.',NULL,'Potatura raramente necessaria; se serve a fine inverno/inizio primavera (senza foglie)','f'),
('cornus_mas','en','Very early bee forage (February/March, yellow flowers before the foliage). Edible, vitamin-rich fruits. Slow-growing, but very long-lived. Suitable for hedging.','Native (Swiss Plateau/Jura, warmth-loving), the most important very early insect food plant. Edible fruits traditionally used for jam.',NULL,'after the fruit harvest or in late winter; tolerates hard pruning','f'),
('cornus_mas','es','Floración melífera muy temprana (febrero/marzo, flores amarillas antes que el follaje). Frutos comestibles ricos en vitaminas. Crecimiento lento, pero muy longevo. Apto para seto.','Autóctono (Meseta suiza/Jura, termófilo), la planta nutricia para insectos más importante a inicio de temporada. Frutos comestibles tradicionalmente para mermelada.',NULL,'tras la cosecha de los frutos o a finales de invierno; tolera una poda fuerte','f'),
('cornus_mas','fr','Floraison mellifère très précoce (février/mars, fleurs jaunes avant le feuillage). Fruits comestibles riches en vitamines. Croissance lente, mais très longévif. Apte à la haie.','Indigène (Plateau suisse/Jura, thermophile), plante nourricière pour insectes la plus importante en toute début de saison. Fruits comestibles traditionnellement pour la confiture.',NULL,'après la récolte des fruits ou en fin d''hiver ; supporte une taille sévère','f'),
('cornus_mas','it','Fioritura mellifera molto precoce (febbraio/marzo, fiori gialli prima del fogliame). Frutti commestibili ricchi di vitamine. Crescita lenta, ma molto longevo. Adatto a siepe.','Indigeno (Altopiano svizzero/Giura, termofilo), pianta nutrice per insetti più importante a inizio stagione. Frutti commestibili tradizionalmente per confettura.',NULL,'dopo la raccolta dei frutti o a fine inverno; tollera una potatura energica','f'),
('cornus_sanguinea','en','Produces root suckers - can spread, watch in small gardens. Decorative red winter twigs (cutting back promotes colouring). Bird-feeding shrub, good bee forage. Fruits slightly toxic when raw - do not eat.','Native, common wild-hedge shrub on the Plateau/Jura. Watch for sucker formation at property boundaries.','raw black fruits mildly toxic/inedible (cornin in bark, leaves, roots); raw consumption can cause gastrointestinal upset','Late winter (coppice for bright red winter twigs); remove suckers','f'),
('cornus_sanguinea','es','Emite renuevos radiculares - puede extenderse, vigilar en jardines pequeños. Ramas rojas decorativas en invierno (la poda favorece la coloración). Arbusto nutricio para aves, buena planta melífera. Frutos ligeramente tóxicos en crudo - no consumir.','Autóctono, arbusto de seto silvestre frecuente en la Meseta/Jura. Atención a la formación de renuevos en los límites de la propiedad.','frutos negros crudos ligeramente tóxicos/no comestibles (cornina en corteza, hojas, raíces); el consumo en crudo puede provocar molestias gastrointestinales','Finales de invierno (cortar a matarrasa para ramas invernales rojo intenso); eliminar los renuevos','f'),
('cornus_sanguinea','fr','Émet des drageons racinaires - peut s''étendre, à surveiller dans les petits jardins. Rameaux rouges décoratifs en hiver (la taille favorise la coloration). Arbuste nourricier pour oiseaux, bonne plante mellifère. Fruits légèrement toxiques crus - ne pas consommer.','Indigène, arbuste de haie sauvage fréquent sur le Plateau/Jura. Attention à la formation de drageons aux limites de propriété.','fruits noirs crus légèrement toxiques/non comestibles (cornine dans l''écorce, les feuilles, les racines) ; la consommation crue peut provoquer des troubles gastro-intestinaux','Fin d''hiver (recéper pour des rameaux d''hiver rouge vif) ; supprimer les drageons','f'),
('cornus_sanguinea','it','Emette polloni radicali - può espandersi, da sorvegliare nei piccoli giardini. Rametti rossi decorativi in inverno (la potatura favorisce la colorazione). Arbusto nutrice per uccelli, buona pianta mellifera. Frutti leggermente tossici da crudi - non consumare.','Indigeno, arbusto da siepe selvatica frequente sull''Altopiano/Giura. Attenzione alla formazione di polloni ai confini di proprietà.','frutti neri crudi leggermente tossici/non commestibili (cornina in corteccia, foglie, radici); il consumo crudo può provocare disturbi gastrointestinali','Fine inverno (ceduare per rametti invernali rosso acceso); rimuovere i polloni','f'),
('corylus_avellana','en','Multi-stemmed shrub, ideal as a free hedge or specimen. Wind-pollinated, cross-pollination increases yield. Very adaptable, undemanding. Thinning/coppicing every few years rejuvenates it. Pollen is a strong early-season allergen.','Native wild shrub throughout CH up to 1500 m, common at forest edges and in hedges. Important bird and bee food shrub (early bloomer, pollen source). Recommended for networking hedges.',NULL,'Winter (after the harvest / before flowering begins January-February)','f'),
('corylus_avellana','es','Arbusto multitronco, ideal en seto libre o como ejemplar aislado. Anemófilo, la polinización cruzada aumenta el rendimiento. Muy adaptable, poco exigente. Aclarar/cortar a matarrasa cada pocos años lo rejuvenece. El polen es un fuerte alérgeno de inicio de temporada.','Leñoso silvestre autóctono en toda la CH hasta 1500 m, frecuente en bordes de bosque y en setos. Importante arbusto nutricio para aves y abejas (floración temprana, fuente de polen). Recomendado para setos de interconexión.',NULL,'Invierno (tras la cosecha / antes del inicio de la floración enero-febrero)','f'),
('corylus_avellana','fr','Arbuste multitige, idéal en haie libre ou en sujet isolé. Anémophile, la pollinisation croisée augmente le rendement. Très adaptable, peu exigeant. Éclaircir/recéper tous les quelques ans le rajeunit. Le pollen est un fort allergène de début de saison.','Ligneux sauvage indigène dans toute la CH jusqu''à 1500 m, fréquent en lisière de forêt et dans les haies. Important arbuste nourricier pour oiseaux et abeilles (floraison précoce, source de pollen). Recommandé pour les haies de mise en réseau.',NULL,'Hiver (après la récolte / avant le début de la floraison janvier-février)','f'),
('corylus_avellana','it','Arbusto multifusto, ideale in siepe libera o come esemplare isolato. Anemofilo, l''impollinazione incrociata aumenta la resa. Molto adattabile, poco esigente. Diradare/ceduare ogni pochi anni lo ringiovanisce. Il polline è un forte allergene di inizio stagione.','Legnoso selvatico indigeno in tutta la CH fino a 1500 m, frequente ai margini dei boschi e nelle siepi. Importante arbusto nutrice per uccelli e api (fioritura precoce, fonte di polline). Raccomandato per siepi di interconnessione.',NULL,'Inverno (dopo la raccolta / prima dell''inizio della fioritura gennaio-febbraio)','f'),
('crataegus_laevigata_paul_s_scarlet','en','Sterile, double-flowered ornamental form – sets hardly any/no fruit. Bee/insect shrub. Mind the thorns. Crataegus is non-toxic (even a medicinal plant – heart/circulation), berries of the wild form are edible. Caution, fire blight host plant (notifiable in CH).','In CH a common street/avenue tree; NON-TOXIC (medicinal plant). IMPORTANT: fire blight host – notifiable in CH (FOAG/PPS), observe planting restrictions in outbreak zones.',NULL,'after flowering (June) or in winter (leafless)','f'),
('crataegus_laevigata_paul_s_scarlet','es','Forma ornamental estéril de flor doble – apenas/no forma frutos. Arbusto para abejas/insectos. Atención a las espinas. El Crataegus no es tóxico (incluso planta medicinal – corazón/circulación), las bayas de la forma silvestre son comestibles. Atención, planta huésped del fuego bacteriano (de declaración obligatoria en CH).','En CH, árbol urbano/de alineación frecuente; NO TÓXICO (planta medicinal). IMPORTANTE: huésped del fuego bacteriano – de declaración obligatoria en CH (OFAG/SPF), respetar las restricciones de plantación en las zonas de presencia.',NULL,'tras la floración (junio) o en invierno (sin hojas)','f'),
('crataegus_laevigata_paul_s_scarlet','fr','Forme ornementale stérile à fleurs doubles – ne forme guère/pas de fruits. Arbuste pour abeilles/insectes. Attention aux épines. Le Crataegus est non toxique (même plante médicinale – cœur/circulation), les baies de la forme sauvage sont comestibles. Attention plante hôte du feu bactérien (à déclaration obligatoire en CH).','En CH, arbre de ville/d''alignement fréquent ; NON TOXIQUE (plante médicinale). IMPORTANT : hôte du feu bactérien – à déclaration obligatoire en CH (OFAG/SPF), respecter les restrictions de plantation dans les zones de présence.',NULL,'après la floraison (juin) ou en hiver (sans feuilles)','f'),
('crataegus_laevigata_paul_s_scarlet','it','Forma ornamentale sterile a fiori doppi – non forma quasi/per nulla frutti. Arbusto per api/insetti. Attenzione alle spine. Il Crataegus è non tossico (anzi pianta medicinale – cuore/circolazione), le bacche della forma selvatica sono commestibili. Attenzione pianta ospite del colpo di fuoco batterico (a notifica obbligatoria in CH).','In CH frequente albero cittadino/da viale; NON TOSSICO (pianta medicinale). IMPORTANTE: ospite del colpo di fuoco batterico – a notifica obbligatoria in CH (UFAG/SPF), rispettare le restrizioni di piantagione nelle zone di presenza.',NULL,'dopo la fioritura (giugno) o in inverno (senza foglie)','f'),
('crataegus_monogyna','en','Very robust, excellent bird food and nesting shrub. The thorns offer protection for breeding birds. Susceptible to fire blight (notifiable in CH).','Native, the most important wild-hedge shrub. Fire blight host plant - in some CH cantons observe planting restrictions in fruit-growing areas.',NULL,'Late winter (February) or after flowering; hedge trimming in June','f'),
('crataegus_monogyna','es','Muy robusto, excelente arbusto nutricio y de nidificación para aves. Las espinas ofrecen protección a las aves nidificantes. Sensible al fuego bacteriano (de declaración obligatoria en CH).','Autóctono, el arbusto de seto silvestre más importante. Planta huésped del fuego bacteriano - en algunos cantones de CH, respetar las restricciones de plantación en las zonas de fruticultura.',NULL,'Finales de invierno (febrero) o tras la floración; recorte del seto en junio','f'),
('crataegus_monogyna','fr','Très robuste, excellent arbuste nourricier et de nidification pour oiseaux. Les épines offrent une protection aux oiseaux nicheurs. Sensible au feu bactérien (à déclaration obligatoire en CH).','Indigène, arbuste de haie sauvage le plus important. Plante hôte du feu bactérien - dans certains cantons CH, respecter les restrictions de plantation dans les zones d''arboriculture fruitière.',NULL,'Fin d''hiver (février) ou après la floraison ; taille de haie en juin','f'),
('crataegus_monogyna','it','Molto robusto, eccellente arbusto nutrice e di nidificazione per uccelli. Le spine offrono protezione agli uccelli nidificanti. Sensibile al colpo di fuoco batterico (a notifica obbligatoria in CH).','Indigeno, arbusto da siepe selvatica più importante. Pianta ospite del colpo di fuoco batterico - in alcuni cantoni CH rispettare le restrizioni di piantagione nelle zone frutticole.',NULL,'Fine inverno (febbraio) o dopo la fioritura; taglio della siepe a giugno','f'),
('cydonia_oblonga','en','Self-fertile, suitable for a single tree. Fruit hard/astringent raw, edible only after cooking (jelly, compote). Susceptible to fire blight. Swallowing the seeds whole is harmless, do not chew them.','Robust old home-garden fruit, widespread in warmer CH locations. Fire blight (Erwinia amylovora) notifiable — as a Rosaceae, a susceptible host.','The seeds (pips) contain cyanogenic glycosides (amygdalin) — do not chew the seeds; the flesh is edible after cooking','Winter (February-March); thin out only sparingly, fruits on the previous year''s wood','f'),
('cydonia_oblonga','es','Autofértil, adecuado para árbol aislado. Fruto duro/áspero en crudo, comestible solo tras la cocción (jalea, compota). Sensible al fuego bacteriano. Tragar las semillas enteras es inofensivo, no masticarlas.','Robusto fruto antiguo de huerto familiar, extendido en las situaciones más cálidas de CH. Fuego bacteriano (Erwinia amylovora) de declaración obligatoria — como rosácea, huésped sensible.','Las semillas (pepitas) contienen glucósidos cianogénicos (amigdalina) — no masticar las semillas; la pulpa es comestible tras la cocción','Invierno (febrero-marzo); aclarar solo moderadamente, fructifica sobre la madera del año anterior','f'),
('cydonia_oblonga','fr','Autofertile, convient à un arbre isolé. Fruit dur/âpre cru, comestible seulement après cuisson (gelée, compote). Sensible au feu bactérien. Avaler les pépins entiers est sans danger, ne pas les mâcher.','Robuste fruit ancien de jardin familial, répandu dans les situations plus chaudes de CH. Feu bactérien (Erwinia amylovora) à déclaration obligatoire — en tant que Rosaceae, hôte sensible.','Les graines (pépins) contiennent des glycosides cyanogènes (amygdaline) — ne pas mâcher les pépins ; la pulpe est comestible après cuisson','Hiver (février-mars) ; éclaircir seulement modérément, fructifie sur le bois de l''année précédente','f'),
('cydonia_oblonga','it','Autofertile, adatto ad albero isolato. Frutto duro/aspro da crudo, commestibile solo dopo cottura (gelatina, composta). Sensibile al colpo di fuoco batterico. Ingerire i semi interi è innocuo, non masticarli.','Robusto frutto antico da orto familiare, diffuso nelle posizioni più calde della CH. Colpo di fuoco batterico (Erwinia amylovora) a notifica obbligatoria — in quanto Rosaceae, ospite sensibile.','I semi (noccioli) contengono glicosidi cianogenici (amigdalina) — non masticare i semi; la polpa è commestibile dopo cottura','Inverno (febbraio-marzo); diradare solo moderatamente, fruttifica sul legno dell''anno precedente','f'),
('euonymus_europaeus','en','WARNING: one of the most dangerous native poisonous plants, one of the ''dangerous four'' (with laburnum, holly, mezereon). The bright fruits magnetically attract children. Do NOT plant in gardens with small children/pets. Ecologically valuable as a food-bearing shrub for birds (non-toxic to them).','Native, ecologically valuable, but HIGHLY POISONOUS – tox.ch lists it as a dangerous poisonous plant. Avoid near kindergartens/playgrounds. Tox emergency line CH: 145.','ALL parts of the plant, especially the bright pink-orange fruits/seeds (cardiac glycosides, alkaloids); as few as 3 seeds can cause severe poisoning in children.','Late winter or after flowering; wear gloves when working.','f'),
('euonymus_europaeus','es','ADVERTENCIA: una de las plantas venenosas autóctonas más peligrosas, forma parte de las « cuatro peligrosas » (junto con el codeso, el acebo, la mezereón). Los frutos llamativos atraen irresistiblemente a los niños. NO plantar en jardines con niños pequeños/mascotas. Ecológicamente valioso como arbusto nutricio para las aves (no tóxico para ellas).','Autóctono, ecológicamente valioso, pero MUY VENENOSO – tox.ch lo cataloga como planta venenosa peligrosa. Evitar cerca de guarderías/parques infantiles. Línea de urgencias Tox CH: 145.','TODAS las partes de la planta, sobre todo los frutos/semillas de color rosa-naranja intenso (glucósidos cardiotónicos, alcaloides); bastan 3 semillas para provocar una intoxicación grave en niños.','Final del invierno o tras la floración; usar guantes durante los trabajos.','f'),
('euonymus_europaeus','fr','AVERTISSEMENT : l''une des plantes toxiques indigènes les plus dangereuses, fait partie des « quatre dangereuses » (avec le cytise, le houx, le bois-gentil). Les fruits éclatants attirent irrésistiblement les enfants. NE PAS planter dans les jardins fréquentés par de jeunes enfants/animaux domestiques. Précieux sur le plan écologique comme arbuste nourricier pour les oiseaux (non toxique pour eux).','Indigène, écologiquement précieux, mais FORTEMENT TOXIQUE – tox.ch le classe parmi les plantes vénéneuses dangereuses. À éviter près des crèches/aires de jeux. Numéro d''urgence Tox CH : 145.','TOUTES les parties de la plante, surtout les fruits/graines rose-orange éclatants (glycosides cardiotoniques, alcaloïdes) ; 3 graines suffisent à provoquer une intoxication grave chez l''enfant.','Fin de l''hiver ou après la floraison ; porter des gants lors des travaux.','f'),
('euonymus_europaeus','it','AVVERTENZA: una delle piante velenose autoctone più pericolose, fa parte delle « quattro pericolose » (insieme a maggiociondolo, agrifoglio, dafne mezereo). I frutti sgargianti attirano irresistibilmente i bambini. NON piantare in giardini con bambini piccoli/animali domestici. Ecologicamente prezioso come arbusto nutrice per gli uccelli (per loro non tossico).','Autoctono, ecologicamente prezioso, ma FORTEMENTE VELENOSO – tox.ch lo elenca tra le piante velenose pericolose. Da evitare presso asili/parchi gioco. Numero d''emergenza Tox CH: 145.','TUTTE le parti della pianta, soprattutto i frutti/semi rosa-arancio sgargianti (glicosidi cardioattivi, alcaloidi); già 3 semi possono provocare un grave avvelenamento nei bambini.','Fine inverno o dopo la fioritura; indossare guanti durante i lavori.','f'),
('fagus_sylvatica','en','Keeps its winter foliage as a privacy screen. Raw beechnuts in quantity are mildly toxic (gastrointestinal upset), roasted they are edible — harmless for normal garden/hedge use, hence child_pet_safe.','Most common broadleaf tree in Switzerland, native up to 1500 m. As a hedge like hornbeam, prefers more permeable soils.','raw beechnuts (fagin/oxalic acid) in larger quantities','June-July and February','f'),
('fagus_sylvatica','es','Conserva su follaje invernal como pantalla de privacidad. Los hayucos crudos en cantidad son ligeramente tóxicos (trastornos gastrointestinales), tostados son comestibles — sin riesgo para el uso normal en jardín/seto, de ahí child_pet_safe.','Árbol caducifolio más común de Suiza, autóctono hasta 1500 m. Como seto, igual que el carpe, prefiere suelos más permeables.','hayucos crudos (fagina/ácido oxálico) en gran cantidad','junio-julio y febrero','f'),
('fagus_sylvatica','fr','Conserve son feuillage hivernal comme écran de protection. Les faînes crues en quantité sont légèrement toxiques (troubles gastro-intestinaux), grillées elles sont comestibles — sans risque pour un usage normal au jardin/en haie, d''où child_pet_safe.','Feuillu le plus répandu de Suisse, indigène jusqu''à 1500 m. En haie comme le charme, préfère les sols plus perméables.','faînes crues (fagine/acide oxalique) en grande quantité','juin-juillet et février','f'),
('fagus_sylvatica','it','Mantiene il fogliame invernale come schermo protettivo. Le faggiole crude in quantità sono leggermente tossiche (disturbi gastrointestinali), tostate sono commestibili — innocue per un uso normale in giardino/siepe, da cui child_pet_safe.','Latifoglia più diffusa della Svizzera, autoctona fino a 1500 m. In siepe come il carpino, predilige suoli più permeabili.','faggiole crude (fagina/acido ossalico) in grande quantità','giugno-luglio e febbraio','f'),
('fragaria_x_ananassa','en','Botanically a herbaceous perennial, not a woody shrub – late-summer planting (July-Sept.) is ideal for harvest the following year. Forms runners (daughter plants) for propagation. Mulching with straw keeps the fruit clean/dry. Renew the bed every 3 years (yield decline, soil fatigue).','In CH the most widely grown garden berry, safe for children and pets. People allergic to birch pollen may react to fresh strawberries (oral allergy syndrome) – hence allergen_potential ''medium''. Up to ~1500 m.',NULL,'after harvest: cut back foliage/runners, replace old plants after 3 years','f'),
('fragaria_x_ananassa','es','Botánicamente una planta herbácea perenne, no un arbusto leñoso – la plantación a finales de verano (julio-sept.) es ideal para la cosecha del año siguiente. Forma estolones (plantas hijas) para la propagación. El acolchado con paja mantiene los frutos limpios/secos. Renovar el bancal cada 3 años (descenso de rendimiento, cansancio del suelo).','En CH la baya de jardín más cultivada, segura para niños y mascotas. Las personas alérgicas al polen de abedul pueden reaccionar a las fresas frescas (síndrome de alergia oral) – de ahí allergen_potential « medio ». Hasta ~1500 m.',NULL,'tras la cosecha: recortar follaje/estolones, sustituir las plantas viejas tras 3 años','f'),
('fragaria_x_ananassa','fr','Plante herbacée vivace sur le plan botanique, et non un arbuste ligneux – plantation en fin d''été (juillet-sept.) idéale pour une récolte l''année suivante. Forme des stolons (plants-filles) pour la multiplication. Le paillage à la paille garde les fruits propres/secs. Renouveler la planche tous les 3 ans (baisse de rendement, fatigue du sol).','En CH la baie de jardin la plus cultivée, sans danger pour enfants et animaux domestiques. Les personnes allergiques au pollen de bouleau peuvent réagir aux fraises fraîches (syndrome d''allergie orale) – d''où allergen_potential « moyen ». Jusqu''à ~1500 m.',NULL,'après la récolte : rabattre le feuillage/les stolons, remplacer les vieux plants après 3 ans','f'),
('fragaria_x_ananassa','it','Pianta erbacea perenne dal punto di vista botanico, non un arbusto legnoso – impianto a fine estate (luglio-set.) ideale per il raccolto dell''anno successivo. Forma stoloni (piante figlie) per la moltiplicazione. La pacciamatura con paglia mantiene i frutti puliti/asciutti. Rinnovare l''aiuola ogni 3 anni (calo di resa, stanchezza del terreno).','In CH la bacca da giardino più coltivata, sicura per bambini e animali domestici. Gli allergici al polline di betulla possono reagire alle fragole fresche (sindrome orale allergica) – da cui allergen_potential « medio ». Fino a ~1500 m.',NULL,'dopo il raccolto: accorciare fogliame/stoloni, sostituire le vecchie piante dopo 3 anni','f'),
('ilex_aquifolium','en','Highly poisonous: red berries — symptoms from about 4 berries, 20-30 berries potentially fatal in children (tox.ch/GIZ). Highly attractive to children. Dioecious: only female plants bear berries, a male pollinator is needed. Native, protected.','Native, protected in several cantons (picking/digging up prohibited). Highly poisonous berries — critical in small children, Tox Info Suisse 145.','red berries (mainly), also leaves (triterpenes, saponins, theobromine, ilicin)','June-July and February-March','f'),
('ilex_aquifolium','es','Muy venenoso: bayas rojas — síntomas a partir de unas 4 bayas, 20-30 bayas potencialmente mortales en niños (tox.ch/GIZ). Muy atractivo para los niños. Dioico: solo las plantas femeninas dan bayas, se necesita un polinizador masculino. Autóctono, protegido.','Autóctono, protegido en varios cantones (recolección/extracción prohibidas). Bayas muy venenosas — crítico en niños pequeños, Tox Info Suisse 145.','bayas rojas (sobre todo), también las hojas (triterpenos, saponinas, teobromina, ilicina)','junio-julio y febrero-marzo','f'),
('ilex_aquifolium','fr','Fortement toxique : baies rouges — symptômes dès env. 4 baies, 20-30 baies potentiellement mortelles chez l''enfant (tox.ch/GIZ). Très attractif pour les enfants. Dioïque : seuls les plants femelles portent des baies, un pollinisateur mâle est nécessaire. Indigène, protégé.','Indigène, protégé dans plusieurs cantons (cueillette/déterrage interdits). Baies fortement toxiques — critique chez les jeunes enfants, Tox Info Suisse 145.','baies rouges (surtout), aussi les feuilles (triterpènes, saponines, théobromine, ilicine)','juin-juillet et février-mars','f'),
('ilex_aquifolium','it','Fortemente velenoso: bacche rosse — sintomi già da ca. 4 bacche, 20-30 bacche potenzialmente letali nei bambini (tox.ch/GIZ). Molto attraente per i bambini. Dioico: solo le piante femminili portano bacche, è necessario un impollinatore maschile. Autoctono, protetto.','Autoctono, protetto in diversi cantoni (raccolta/estirpazione vietate). Bacche fortemente velenose — critico nei bambini piccoli, Tox Info Suisse 145.','bacche rosse (soprattutto), anche le foglie (triterpeni, saponine, teobromina, ilicina)','giugno-luglio e febbraio-marzo','f'),
('juglans_regia','en','Needs deep, moist soil. Juglone inhibits underplanting (allelopathy) – no vegetable bed beneath it. Susceptible to late frost at bud break. Prune only in late summer, otherwise heavy sap flow. Large final tree – keep distance from buildings due to taproot and crown width.','In CH found up to about 800 m, a traditional farmstead tree on the Plateau and in the valleys. Provides the walnut (Nidwalden farmstead tree). Late frost at higher elevations limits the yield.','Green husks, leaves and roots contain juglone (allelopathic, mildly irritant); for horses/dogs, mouldy nuts and the heartwood are problematic (laminitis risk in horses)','late summer (August), never in spring due to heavy bleeding','f'),
('juglans_regia','es','Requiere suelo profundo y fresco. La juglona inhibe la plantación bajo la copa (alelopatía) – sin huerto debajo. Sensible a las heladas tardías en la brotación. Podar solo a finales de verano, de lo contrario fuerte flujo de savia. Gran árbol de plantación final – mantener distancia a los edificios por la raíz pivotante y la anchura de la copa.','En CH presente hasta unos 800 m, árbol de granja tradicional en la Meseta y en los valles. Da la nuez (árbol de granja de Nidwalden). Las heladas tardías en altitud limitan el rendimiento.','Las cáscaras verdes, las hojas y las raíces contienen juglona (alelopática, ligeramente irritante); para caballos/perros las nueces enmohecidas y el duramen son problemáticos (riesgo de laminitis en el caballo)','final del verano (agosto), nunca en primavera por el fuerte sangrado','f'),
('juglans_regia','fr','Sol profond et frais nécessaire. La juglone inhibe les plantations sous le houppier (allélopathie) – pas de potager dessous. Sensible aux gelées tardives au débourrement. Taille uniquement en fin d''été, sinon fort écoulement de sève. Grand arbre de fin de plantation – respecter la distance aux bâtiments en raison du pivot et de la largeur de la couronne.','En CH répandu jusqu''à env. 800 m, arbre de ferme traditionnel sur le Plateau et dans les vallées. Fournit la noix (arbre de ferme nidwaldien). Les gelées tardives en altitude limitent le rendement.','Les brous verts, les feuilles et les racines contiennent de la juglone (allélopathique, légèrement irritante) ; pour les chevaux/chiens, les noix moisies et le bois de cœur sont problématiques (risque de fourbure chez le cheval)','fin de l''été (août), jamais au printemps en raison du fort écoulement de sève','f'),
('juglans_regia','it','Necessita di suolo profondo e fresco. Il juglone inibisce le piante sotto la chioma (allelopatia) – niente orto sottostante. Sensibile alle gelate tardive al germogliamento. Potatura solo a fine estate, altrimenti forte flusso di linfa. Grande albero da fine impianto – rispettare la distanza dagli edifici a causa del fittone e dell''ampiezza della chioma.','In CH diffuso fino a ca. 800 m, albero da fattoria tradizionale dell''Altopiano e delle valli. Fornisce la noce (albero da fattoria nidvaldese). Le gelate tardive in quota limitano la resa.','I malli verdi, le foglie e le radici contengono juglone (allelopatico, leggermente irritante); per cavalli/cani le noci ammuffite e il durame sono problematici (rischio di laminite nel cavallo)','fine estate (agosto), mai in primavera a causa del forte trasudamento','f'),
('juniperus_communis','en','Only mildly toxic – the ripe berries are the well-known culinary spice and not dangerous to children/pets. Beware of confusion with the HIGHLY poisonous savin (Juniperus sabina). Skin irritation possible from the essential oils.','Native, from the lowlands up to ~2500 m a.s.l.; protected, on nutrient-poor sites and juniper heaths. Pear rust: do not plant next to pear trees (alternate host).','Needles and berry cones contain essential oils (including terpinen-4-ol); in larger amounts irritant to the kidneys and stomach. Ripe berries are edible in culinary amounts (spice), to be avoided in overdose and during pregnancy (uterine action).','spring; shape pruning only, barely re-sprouts from old wood','f'),
('juniperus_communis','es','Solo ligeramente tóxico – las bayas maduras son la conocida especia de cocina y no son peligrosas para niños/mascotas. Cuidado con la confusión con la sabina (Juniperus sabina), MUY venenosa. Posible irritación cutánea por los aceites esenciales.','Autóctono, desde las tierras bajas hasta unos ~2500 m s.n.m.; protegido, en estaciones pobres y brezales de enebro. Roya reticular del peral: no plantar junto a perales (huésped intermedio).','Las acículas y los conos-baya contienen aceites esenciales (entre otros terpinen-4-ol); en grandes cantidades irritan riñones y estómago. Las bayas maduras son comestibles en cantidades culinarias (especia), a evitar en sobredosis y durante el embarazo (acción uterina).','primavera; solo poda de formación, apenas rebrota de la madera vieja','f'),
('juniperus_communis','fr','Seulement légèrement toxique – les baies mûres sont l''épice de cuisine bien connue et ne sont pas dangereuses pour les enfants/animaux domestiques. Attention à la confusion avec la sabine (Juniperus sabina), FORTEMENT toxique. Irritation cutanée possible due aux huiles essentielles.','Indigène, de la plaine jusqu''à ~2500 m d''altitude ; protégé, sur les stations maigres et les landes à genévrier. Rouille grillagée du poirier : ne pas planter à côté des poiriers (hôte intermédiaire).','Les aiguilles et les cônes-baies contiennent des huiles essentielles (entre autres le terpinène-4-ol) ; en grande quantité irritants pour les reins et l''estomac. Les baies mûres sont consommables en quantités culinaires (épice), à éviter en surdose et pendant la grossesse (action utérine).','printemps ; uniquement taille de forme, ne repart guère du vieux bois','f'),
('juniperus_communis','it','Solo leggermente tossico – le bacche mature sono la nota spezia da cucina e non sono pericolose per bambini/animali domestici. Attenzione alla confusione con la sabina (Juniperus sabina), FORTEMENTE velenosa. Possibile irritazione cutanea dovuta agli oli essenziali.','Autoctono, dalla pianura fino a ~2500 m s.l.m.; protetto, su stazioni magre e brughiere a ginepro. Ruggine reticolata del pero: non piantare accanto ai peri (ospite intermedio).','Gli aghi e i coni-bacca contengono oli essenziali (tra cui terpinen-4-olo); in grandi quantità irritanti per reni e stomaco. Le bacche mature sono commestibili in quantità da cucina (spezia), da evitare in sovradosaggio e in gravidanza (azione uterina).','primavera; solo potatura di forma, ricaccia a stento dal legno vecchio','f'),
('laburnum_watereri_vossii','en','WARNING: highly poisonous (cytisine) – one of the most dangerous ornamental garden plants. The pea-like seeds/pods are especially enticing to children and potentially fatal. Do NOT plant in children''s/play areas, schools, daycares. ''Vossii'' sets fewer seeds but is nonetheless poisonous. If poisoning is suspected, call the Tox centre 145 (CH) immediately.','A widespread ornamental shrub in CH, but tox.ch lists laburnum as FATALLY poisonous – frequent poisoning reports in children. child_pet_safe=false mandatory. Swiss Tox emergency line: 145.','ALL parts of the plant, especially the seeds and pods (cytisine); a few seeds can be life-threatening for children.','after flowering (June/July); prune as little as possible, poor wound healing','f'),
('laburnum_watereri_vossii','es','ADVERTENCIA: muy venenoso (citisina) – una de las plantas ornamentales de jardín más peligrosas. Las semillas/vainas, parecidas a guisantes, resultan especialmente atractivas para los niños y son potencialmente mortales. NO plantar en zonas infantiles/de juego, escuelas, guarderías. « Vossii » produce menos semillas, pero sigue siendo venenoso. Ante la sospecha, llamar de inmediato al centro Tox 145 (CH).','Arbusto ornamental extendido en CH, pero tox.ch cataloga el codeso como MORTALMENTE venenoso – frecuentes avisos de intoxicación en niños. child_pet_safe=false obligatorio. Línea de urgencias Tox suiza: 145.','TODAS las partes de la planta, sobre todo las semillas y las vainas (citisina); unas pocas semillas pueden poner en peligro la vida de un niño.','tras la floración (junio/julio); podar lo menos posible, mala cicatrización de las heridas','f'),
('laburnum_watereri_vossii','fr','AVERTISSEMENT : très toxique (cytisine) – l''une des plantes ornementales de jardin les plus dangereuses. Les graines/gousses, semblables à des petits pois, sont particulièrement attirantes pour les enfants et potentiellement mortelles. NE PAS planter dans les espaces enfants/de jeux, écoles, crèches. « Vossii » produit moins de graines, mais reste néanmoins toxique. En cas de suspicion, appeler immédiatement le centre Tox 145 (CH).','Arbuste ornemental répandu en CH, mais tox.ch classe le cytise comme MORTELLEMENT toxique – signalements fréquents d''intoxications chez les enfants. child_pet_safe=false impératif. Numéro d''urgence Tox suisse : 145.','TOUTES les parties de la plante, surtout les graines et les gousses (cytisine) ; quelques graines peuvent mettre en danger la vie d''un enfant.','après la floraison (juin/juillet) ; tailler le moins possible, mauvaise cicatrisation des plaies','f'),
('laburnum_watereri_vossii','it','AVVERTENZA: altamente velenoso (citisina) – una delle piante ornamentali da giardino più pericolose. I semi/baccelli simili a piselli sono particolarmente allettanti per i bambini e potenzialmente letali. NON piantare in aree per bambini/gioco, scuole, asili. « Vossii » produce meno semi, ma è comunque velenoso. In caso di sospetto chiamare subito il centro Tox 145 (CH).','Arbusto ornamentale diffuso in CH, ma tox.ch classifica il maggiociondolo come MORTALMENTE velenoso – frequenti segnalazioni di avvelenamento nei bambini. child_pet_safe=false imperativo. Numero d''emergenza Tox svizzero: 145.','TUTTE le parti della pianta, soprattutto i semi e i baccelli (citisina); pochi semi possono essere letali per i bambini.','dopo la fioritura (giugno/luglio); potare il meno possibile, scarsa cicatrizzazione delle ferite','f'),
('larix_decidua','en','The only native conifer that sheds its needles in winter (deciduous). Deep to heart-rooting, storm-resistant, low risk to buildings. Needs full sun.','A high-elevation/mountain tree, up to ~2500 m a.s.l. (Engadine, Valais). Climate-resilient in the subalpine zone; more disease-prone in the lowlands (larch canker).',NULL,'rarely needed; winter (leafless)','f'),
('larix_decidua','es','Única conífera autóctona que pierde las acículas en invierno (caducifolia). Enraizamiento profundo a en corazón, resistente a las tormentas, bajo riesgo para los edificios. Necesita pleno sol.','Árbol de altitud/de montaña, hasta unos ~2500 m s.n.m. (Engadina, Valais). Resiliente al clima en el piso subalpino; más propenso a enfermedades en las tierras bajas (chancro del alerce).',NULL,'raramente necesaria; invierno (sin follaje)','f'),
('larix_decidua','fr','Seul conifère indigène qui perd ses aiguilles en hiver (caducifolié). Enracinement profond à traçant en cœur, résistant aux tempêtes, faible risque pour les bâtiments. A besoin de plein soleil.','Arbre d''altitude/de montagne, jusqu''à ~2500 m d''altitude (Engadine, Valais). Résilient au climat à l''étage subalpin ; plus sensible aux maladies en plaine (chancre du mélèze).',NULL,'rarement nécessaire ; hiver (sans feuillage)','f'),
('larix_decidua','it','Unica conifera autoctona che perde gli aghi in inverno (decidua). Radicamento profondo a cuore, resistente alle tempeste, basso rischio per gli edifici. Necessita di pieno sole.','Albero d''alta quota/di montagna, fino a ~2500 m s.l.m. (Engadina, Vallese). Resiliente al clima nel piano subalpino; più soggetto a malattie in pianura (cancro del larice).',NULL,'raramente necessaria; inverno (senza fogliame)','f'),
('ligustrum_ovalifolium','en','Very tolerant of pruning, ideal for a formal hedge. Berries mildly toxic (ligustrin/syringin) — vomiting/diarrhoea in children. Pruning before flowering reduces pollen release.','A very widespread clipped hedge on the Plateau. In a poisoning emergency, Tox Info Suisse 145.','berries (black), leaves','May-September (twice a year for a dense hedge)','f'),
('ligustrum_ovalifolium','es','Muy tolerante a la poda, ideal para seto formal. Bayas ligeramente tóxicas (ligustrina/siringina) — vómitos/diarrea en niños. Podar antes de la floración reduce la dispersión del polen.','Seto formal muy extendido en la Meseta. En caso de emergencia por intoxicación, Tox Info Suisse 145.','bayas (negras), hojas','mayo-septiembre (2 veces al año para un seto denso)','f'),
('ligustrum_ovalifolium','fr','Très tolérant à la taille, idéal pour haie taillée. Baies légèrement toxiques (ligustrine/syringine) — vomissements/diarrhée chez l''enfant. Une taille avant la floraison réduit la dispersion du pollen.','Haie taillée très répandue sur le Plateau. En cas d''urgence toxicologique, Tox Info Suisse 145.','baies (noires), feuilles','mai-septembre (2x par an pour une haie dense)','f'),
('ligustrum_ovalifolium','it','Molto tollerante alla potatura, ideale per siepe formale. Bacche leggermente tossiche (ligustrina/siringina) — vomito/diarrea nei bambini. Una potatura prima della fioritura riduce la dispersione del polline.','Siepe formale molto diffusa sull''Altopiano. In caso di emergenza da avvelenamento, Tox Info Suisse 145.','bacche (nere), foglie','maggio-settembre (2 volte l''anno per una siepe fitta)','f'),
('ligustrum_vulgare','en','Berries mildly toxic — vomiting/diarrhoea in children, problematic for dogs. Native, ecologically valuable (butterflies, birds) when unpruned. Very robust and lime-loving.','Native, a wild/natural hedge species. Berries mildly toxic — Tox Info Suisse 145.','berries (black) and leaves (ligustrin, syringin)','May-September (several times); unpruned, flowers/berries for wildlife','f'),
('ligustrum_vulgare','es','Bayas ligeramente tóxicas — vómitos/diarrea en niños, problemáticas para los perros. Autóctono, ecológicamente valioso (mariposas, aves) si no se poda. Muy robusto y calcícola.','Autóctono, especie de seto silvestre/natural. Bayas ligeramente tóxicas — Tox Info Suisse 145.','bayas (negras) y hojas (ligustrina, siringina)','mayo-septiembre (varias veces); sin podar, flores/bayas para la fauna silvestre','f'),
('ligustrum_vulgare','fr','Baies légèrement toxiques — vomissements/diarrhée chez l''enfant, problématique pour les chiens. Indigène, écologiquement précieux (papillons, oiseaux) si non taillé. Très robuste et calcicole.','Indigène, espèce de haie sauvage/naturelle. Baies légèrement toxiques — Tox Info Suisse 145.','baies (noires) et feuilles (ligustrine, syringine)','mai-septembre (plusieurs fois) ; non taillé, fleurs/baies pour la faune sauvage','f'),
('ligustrum_vulgare','it','Bacche leggermente tossiche — vomito/diarrea nei bambini, problematiche per i cani. Autoctono, ecologicamente prezioso (farfalle, uccelli) se non potato. Molto robusto e calcicolo.','Autoctono, specie da siepe selvatica/naturale. Bacche leggermente tossiche — Tox Info Suisse 145.','bacche (nere) e foglie (ligustrina, siringina)','maggio-settembre (più volte); non potato, fiori/bacche per la fauna selvatica','f'),
('liquidambar_styraciflua','en','Large tree with spectacular autumn colour (yellow-orange-purple). The spiny fruit capsules can be a tripping/lawnmower hazard – choose low-fruiting cultivars (''Worplesdon''). Calcifuge, prefers slightly acidic, fresh soil. Large specimen at maturity – allow sufficient spacing.','In CH increasingly planted as a climate-resilient park/street tree; non-toxic. As a forest/large tree, keep sufficient distance from buildings (mature height up to 20 m) – height_class=forst consistent.',NULL,'Winter (leafless) to early spring; train the scaffold branches while young','f'),
('liquidambar_styraciflua','es','Árbol grande con espectacular coloración otoñal (amarillo-naranja-púrpura). Las cápsulas espinosas de los frutos pueden suponer un obstáculo (tropiezo/cortacésped) – elegir variedades de poca fructificación (''Worplesdon''). Calcífugo, prefiere suelo ligeramente ácido y fresco. Ejemplar grande en su madurez – dejar suficiente distancia.','En CH cada vez más plantado como árbol de parque/alineación resistente al clima; no tóxico. Como árbol grande/forestal, mantener distancia suficiente a los edificios (altura adulta hasta 20 m) – height_class=forst coherente.',NULL,'Invierno (sin hojas) hasta principios de primavera; formar la estructura de ramas en ejemplares jóvenes','f'),
('liquidambar_styraciflua','fr','Grand arbre au feuillage automnal spectaculaire (jaune-orange-pourpre). Les capsules de fruits épineuses peuvent constituer un obstacle (trébuchement/tondeuse) – choisir des variétés peu fructifères (''Worplesdon''). Évite le calcaire, préfère un sol légèrement acide et frais. Grand sujet en taille adulte – prévoir un espace suffisant.','En CH, de plus en plus planté comme arbre de parc/d''alignement résistant au climat ; non toxique. En tant que grand arbre/sujet forestier, prévoir une distance suffisante aux bâtiments (hauteur adulte jusqu''à 20 m) – height_class=forst cohérent.',NULL,'Hiver (sans feuilles) jusqu''au début du printemps ; former la charpente jeune','f'),
('liquidambar_styraciflua','it','Grande albero dal fogliame autunnale spettacolare (giallo-arancio-porpora). Le capsule spinose dei frutti possono costituire un ostacolo (inciampo/tosaerba) – scegliere varietà poco fruttifere (''Worplesdon''). Calcifugo, preferisce un suolo leggermente acido e fresco. Grande esemplare allo stadio adulto – prevedere spazio sufficiente.','In CH sempre più piantato come albero da parco/viale resistente al clima; non tossico. Come grande albero/esemplare forestale prevedere distanza sufficiente dagli edifici (altezza adulta fino a 20 m) – height_class=forst coerente.',NULL,'Inverno (senza foglie) fino all''inizio della primavera; formare la struttura delle branche da giovane','f'),
('lonicera_caerulea_var_kamtschatica','en','IMPORTANT: only the blue-fruited var. kamtschatica/edulis is edible – the native red-/black-fruited honeysuckles (L. xylosteum, L. nigra) are toxic! This cultivar is the edible exception of the genus. Very early ripening (May/June), extremely frost-hardy. Self-sterile: plant two different cultivars for a crop.','In CH the earliest soft fruit and extremely winter-hardy (down to -40 °C), also suited to elevations up to ~1800 m. Edible and safe – but risk of confusion with toxic native honeysuckles: use only purchased edible cultivars. Needs a pollinator cultivar.',NULL,'after harvest / late winter (little pruning needed)','f'),
('lonicera_caerulea_var_kamtschatica','es','IMPORTANTE: solo la var. kamtschatica/edulis de frutos azules es comestible – las madreselvas autóctonas de frutos rojos/negros (L. xylosteum, L. nigra) son tóxicas. Esta variedad es la excepción comestible del género. Maduración muy temprana (mayo/junio), extremadamente resistente a las heladas. Autoestéril: plantar dos variedades distintas para obtener cosecha.','En CH es el primer fruto pequeño de la temporada y extremadamente resistente al invierno (hasta -40 °C), apto también para altitudes de hasta ~1800 m. Comestible y seguro – pero riesgo de confusión con las madreselvas autóctonas tóxicas: usar solo variedades comestibles compradas. Necesita una variedad polinizadora.',NULL,'tras la cosecha / final del invierno (poca poda necesaria)','f'),
('lonicera_caerulea_var_kamtschatica','fr','IMPORTANT : seule la var. kamtschatica/edulis à fruits bleus est comestible – les chèvrefeuilles indigènes à fruits rouges/noirs (L. xylosteum, L. nigra) sont toxiques ! Cette variété est l''exception comestible du genre. Mûrissement très précoce (mai/juin), extrêmement rustique. Autostérile : planter deux variétés différentes pour obtenir une récolte.','En CH, premier petit fruit de la saison et extrêmement rustique (jusqu''à -40 °C), convient aussi aux altitudes jusqu''à ~1800 m. Comestible et sûr – mais risque de confusion avec les chèvrefeuilles indigènes toxiques : n''utiliser que des variétés comestibles achetées. Nécessite une variété pollinisatrice.',NULL,'après la récolte / fin d''hiver (peu de taille nécessaire)','f'),
('lonicera_caerulea_var_kamtschatica','it','IMPORTANTE: solo la var. kamtschatica/edulis a frutti blu è commestibile – i caprifogli indigeni a frutti rossi/neri (L. xylosteum, L. nigra) sono velenosi! Questa varietà è l''eccezione commestibile del genere. Maturazione molto precoce (maggio/giugno), estremamente resistente al gelo. Autosterile: piantare due varietà diverse per ottenere un raccolto.','In CH primo piccolo frutto della stagione ed estremamente resistente al gelo (fino a -40 °C), adatto anche alle quote fino a ~1800 m. Commestibile e sicuro – ma rischio di confusione con i caprifogli indigeni velenosi: usare solo varietà commestibili acquistate. Richiede una varietà impollinatrice.',NULL,'dopo il raccolto / fine inverno (poca potatura necessaria)','f'),
('magnolia_soulangeana','en','Early flowering – blossoms are frost-sensitive, so choose a sheltered spot with little late-frost exposure. Fleshy, shallow, sensitive roots that should not be disturbed. Mulch, do not compact the soil. Pruning only minimal.','In CH a popular front-garden tree on the Central Plateau; non-toxic, safe for children and pets. Shallow-rooted – keep distance from paths/paving.',NULL,'avoid pruning; if necessary in high summer (July/Aug) after flowering, as it bleeds late','f'),
('magnolia_soulangeana','es','Floración temprana – las flores son sensibles a las heladas, por lo que conviene elegir un emplazamiento resguardado y poco expuesto a las heladas tardías. Raíces carnosas y superficiales, delicadas, que no deben perturbarse. Acolchar, no compactar el suelo. Poda solo mínima.','En CH es un árbol apreciado para antejardines en la Meseta; no tóxico, seguro para niños y mascotas. Enraizamiento superficial – mantener distancia respecto a caminos/losas.',NULL,'evitar la poda; si es necesario, en pleno verano (julio/agosto) tras la floración, ya que sangra tardíamente','f'),
('magnolia_soulangeana','fr','Floraison précoce – fleurs sensibles au gel, choisir donc un emplacement abrité et peu sujet aux gelées tardives. Racines charnues et superficielles, fragiles, à ne pas déranger. Pailler, ne pas compacter le sol. Taille uniquement minimale.','En CH, arbre d''avant-jardin apprécié du Plateau ; non toxique, sûr pour enfants et animaux. Enracinement superficiel – respecter une distance avec les chemins/dalles.',NULL,'éviter la taille ; si nécessaire en plein été (juillet/août) après la floraison, car saigne tardivement','f'),
('magnolia_soulangeana','it','Fioritura precoce – fiori sensibili al gelo, scegliere quindi una posizione riparata e poco soggetta alle gelate tardive. Radici carnose e superficiali, delicate, da non disturbare. Pacciamare, non compattare il suolo. Potatura solo minima.','In CH apprezzato albero da giardino anteriore sull''Altopiano; non tossico, sicuro per bambini e animali domestici. Apparato radicale superficiale – mantenere distanza da vialetti/lastre.',NULL,'evitare la potatura; se necessario in piena estate (luglio/agosto) dopo la fioritura, poiché trasuda tardivamente','f'),
('malus_domestica','en','Espalier or standard tree; choose a suitable rootstock (M9 dwarfing, A2 vigorous). Regular formative and thinning pruning. Permanent stake for dwarfing rootstocks.','The most common fruit tree in Switzerland; standard apple trees shape the cultivated landscape and are partly eligible for direct payments. Fire blight (Erwinia amylovora) is notifiable.','The pips (seeds) contain cyanogenic glycosides (amygdalin); the fruit flesh is edible','Winter (February-March) and summer pruning July/August','f'),
('malus_domestica','es','En espaldera o de tronco alto; atender a un patrón adecuado (M9 de escaso vigor, A2 vigoroso). Poda de formación y de aclareo regular. Tutor permanente en patrones poco vigorosos.','El árbol frutal más común de Suiza; los manzanos de tronco alto caracterizan el paisaje cultivado y en parte son elegibles para pagos directos. El fuego bacteriano (Erwinia amylovora) es de declaración obligatoria.','Las pepitas (semillas) contienen glucósidos cianogénicos (amigdalina); la pulpa del fruto es comestible','Invierno (febrero-marzo) y poda en verde julio/agosto','f'),
('malus_domestica','fr','En espalier ou en haute-tige ; veiller à un porte-greffe adapté (M9 faible vigueur, A2 vigoureux). Taille de formation et d''éclaircissage régulière. Tuteur permanent pour les porte-greffes peu vigoureux.','Arbre fruitier le plus répandu de Suisse ; les pommiers haute-tige marquent le paysage cultivé et sont en partie éligibles aux paiements directs. Le feu bactérien (Erwinia amylovora) est soumis à déclaration obligatoire.','Les pépins (graines) contiennent des glycosides cyanogènes (amygdaline) ; la pulpe du fruit est comestible','Hiver (février-mars) et taille en vert juillet/août','f'),
('malus_domestica','it','A spalliera o ad alto fusto; prestare attenzione a un portinnesto adatto (M9 poco vigoroso, A2 vigoroso). Potatura di formazione e di diradamento regolare. Tutore permanente per i portinnesti poco vigorosi.','Albero da frutto più diffuso della Svizzera; i meli ad alto fusto caratterizzano il paesaggio coltivato e sono in parte ammissibili ai pagamenti diretti. Il colpo di fuoco batterico (Erwinia amylovora) è soggetto a obbligo di notifica.','I semi (noccioli) contengono glicosidi cianogenici (amigdalina); la polpa del frutto è commestibile','Inverno (febbraio-marzo) e potatura verde luglio/agosto','f'),
('malus_evereste','en','Valuable pollen source for bees and a good pollinator for dessert apples. The ornamental fruits stay on the tree for a long time, food for birds. The flesh is non-toxic, but the seeds contain amygdalin – large amounts of chewed seeds are cyanogenic.','In CH a very common garden tree and pollinator for orchards. CORRECTED: child_pet_safe changed from true→false, as the seeds contain amygdalin (conservative child/pet protection); the flesh itself is harmless.','Seeds/pips (amygdalin – cyanogenic); the flesh is edible/non-toxic','Winter (leafless, Nov–Feb) or after flowering for shaping cuts','f'),
('malus_evereste','es','Valioso aporte de polen para las abejas y buen polinizador de manzanos de mesa. Los frutos ornamentales permanecen largo tiempo en el árbol, alimento para los pájaros. La pulpa es no tóxica, pero las semillas contienen amigdalina – grandes cantidades de semillas masticadas son cianogénicas.','En CH es un árbol de jardín muy extendido y polinizador para los huertos. CORREGIDO: child_pet_safe cambiado de true→false, ya que las semillas contienen amigdalina (protección conservadora de niños/mascotas); la pulpa en sí es inofensiva.','Semillas/pepitas (amigdalina – cianogénica); la pulpa es comestible/no tóxica','Invierno (sin hojas, nov-feb) o tras la floración para la poda de formación','f'),
('malus_evereste','fr','Précieux pollinisateur pour les abeilles et bon pollinisateur des pommes de table. Les fruits ornementaux restent longtemps accrochés, nourriture pour les oiseaux. La pulpe est non toxique, mais les pépins contiennent de l''amygdaline – de grandes quantités de pépins mâchés sont cyanogènes.','En CH, arbre de jardin très répandu et pollinisateur pour les vergers. CORRIGÉ : child_pet_safe passé de true→false, car les pépins contiennent de l''amygdaline (protection conservatrice des enfants/animaux) ; la pulpe elle-même est inoffensive.','Graines/pépins (amygdaline – cyanogène) ; la pulpe est comestible/non toxique','Hiver (sans feuilles, nov.-fév.) ou après la floraison pour la taille de formation','f'),
('malus_evereste','it','Prezioso fornitore di polline per le api e buon impollinatore per le mele da tavola. I frutti ornamentali restano a lungo sull''albero, nutrimento per gli uccelli. La polpa è non tossica, ma i semi contengono amigdalina – grandi quantità di semi masticati sono cianogene.','In CH albero da giardino molto diffuso e impollinatore per i frutteti. CORRETTO: child_pet_safe da true→false, poiché i semi contengono amigdalina (protezione conservativa per bambini/animali domestici); la polpa stessa è innocua.','Semi/noccioli (amigdalina – cianogena); la polpa è commestibile/non tossica','Inverno (senza foglie, nov-feb) oppure dopo la fioritura per la potatura di forma','f'),
('mespilus_germanica','en','Old fruit species, a picturesque small tree/large shrub with large white flowers. The fruits (medlars) are only edible once softened after frost (bletting/storage), traditionally for purée/jelly. Heat-loving, sheltered location. Usually grafted on hawthorn/quince.','An old, now rare fruit species for warm CH locations up to about 800 m (Central Plateau, Ticino). Worth preserving in home gardens and old orchards. "Asperl" as the Alemannic vernacular name.','The fruits are only edible after frost/bletting (storage) – raw they are hard and rich in tannins, but not toxic. As in many Rosaceae, do not chew the seeds (traces of prussic acid in the seeds); the flesh is harmless','Winter (dormancy), little pruning needed','f'),
('mespilus_germanica','es','Antigua especie frutal, pintoresco arbolito/arbusto grande con grandes flores blancas. Los frutos (níscalos/nísperos europeos) solo son comestibles ablandados tras la helada (maduración por reblandecimiento/almacenamiento), tradicionalmente para compota/jalea. Termófilo, ubicación resguardada. Injertado por lo general sobre espino albar/membrillero.','Antigua especie frutal hoy escasa, para emplazamientos cálidos de CH hasta unos 800 m (Meseta, Tesino). Conviene conservarla en huertos familiares y antiguos vergeles. «Asperl» como nombre vernáculo alemánico.','Los frutos solo son comestibles tras la helada/reblandecimiento (almacenamiento) – crudos son duros y ricos en taninos, pero no tóxicos. Como en muchas rosáceas, no masticar las semillas (trazas de ácido cianhídrico en ellas); la pulpa es inofensiva','Invierno (reposo vegetativo), poca poda necesaria','f'),
('mespilus_germanica','fr','Ancienne espèce fruitière, petit arbre/grand arbuste pittoresque aux grandes fleurs blanches. Les fruits (nèfles) ne sont comestibles que ramollis après le gel (blettissement/conservation), traditionnellement pour compote/gelée. Thermophile, emplacement abrité. Greffé le plus souvent sur aubépine/cognassier.','Ancienne espèce fruitière devenue rare, pour les situations chaudes de CH jusqu''à env. 800 m (Plateau, Tessin). À conserver dans les jardins familiaux et les anciens vergers. « Asperl » comme nom vernaculaire alémanique.','Les fruits ne sont consommables qu''après le gel/blettissement (conservation) – crus, ils sont durs et riches en tanins, mais non toxiques. Comme chez de nombreuses Rosacées, ne pas mâcher les pépins (traces d''acide cyanhydrique dans les graines), la pulpe est sans danger','Hiver (repos végétatif), peu de taille nécessaire','f'),
('mespilus_germanica','it','Antica specie da frutto, pittoresco alberello/grande arbusto con grandi fiori bianchi. I frutti (nespole) sono commestibili solo ammorbiditi dopo il gelo (ammezzimento/conservazione), tradizionalmente per composta/gelatina. Termofilo, posizione riparata. Innestato per lo più su biancospino/cotogno.','Antica specie da frutto divenuta rara, per le posizioni calde della CH fino a ca. 800 m (Altopiano, Ticino). Da conservare nei giardini familiari e nei vecchi frutteti. «Asperl» come nome dialettale alemanno.','I frutti sono commestibili solo dopo il gelo/ammezzimento (conservazione) – crudi sono duri e ricchi di tannini, ma non velenosi. Come in molte Rosacee non masticare i semi (tracce di acido cianidrico nei semi), la polpa è innocua','Inverno (riposo vegetativo), poca potatura necessaria','f'),
('morus_nigra','en','Heat-loving, needs a sheltered, sunny location. Ripe berries stain heavily (stains on paving/terrace) → consider root_risk and location, do not plant above a seating area/paving. Delicious dark berries are edible. Long-lived, gnarled character tree. More frost-sensitive than M. alba.','Heat-demanding – in CH only sensible in mild, sheltered locations (Ticino, Lake Geneva region, Valais, warm urban sites) up to about 700 m. Historically linked to silkworm rearing in Ticino (there rather M. alba).',NULL,'Winter (dormancy), prune sparingly, bleeds with spring pruning','f'),
('morus_nigra','es','Termófilo, necesita un emplazamiento resguardado y soleado. Las bayas maduras manchan intensamente (manchas en pavimento/terraza) → tener en cuenta el root_risk y la ubicación, no plantar sobre una zona de estar/pavimento. Deliciosas bayas oscuras comestibles. Longevo, árbol de carácter nudoso. Más sensible a las heladas que M. alba.','Exigente en calor – en CH solo tiene sentido en ubicaciones suaves y resguardadas (Tesino, región del lago Lemán, Valais, sitios urbanos cálidos) hasta unos 700 m. Históricamente vinculado a la sericultura en el Tesino (allí más bien M. alba).',NULL,'Invierno (reposo vegetativo), poda parca, sangra con la poda primaveral','f'),
('morus_nigra','fr','Thermophile, nécessite un emplacement abrité et ensoleillé. Les baies mûres tachent fortement (taches sur pavés/terrasse) → tenir compte du root_risk et de l''emplacement, ne pas planter au-dessus d''une terrasse/d''un revêtement. Délicieuses baies foncées comestibles. Longévif, arbre de caractère noueux. Plus sensible au gel que M. alba.','Exigeant en chaleur – en CH, judicieux uniquement dans les situations douces et abritées (Tessin, région lémanique, Valais, sites urbains chauds) jusqu''à env. 700 m. Historiquement lié à la sériciculture au Tessin (là plutôt M. alba).',NULL,'Hiver (repos végétatif), taille parcimonieuse, saigne lors d''une taille printanière','f'),
('morus_nigra','it','Termofilo, necessita di una posizione riparata e soleggiata. Le bacche mature macchiano fortemente (macchie su pavimentazione/terrazza) → considerare il root_risk e la posizione, non piantare sopra una zona di seduta/pavimentazione. Deliziose bacche scure commestibili. Longevo, albero dal carattere nodoso. Più sensibile al gelo di M. alba.','Esigente in calore – in CH sensato solo in posizioni miti e riparate (Ticino, regione del Lemano, Vallese, siti urbani caldi) fino a ca. 700 m. Storicamente legato alla bachicoltura in Ticino (lì piuttosto M. alba).',NULL,'Inverno (riposo vegetativo), potatura parsimoniosa, trasuda con la potatura primaverile','f'),
('photinia_x_fraseri_red_robin','en','Slightly toxic (prunasin in the seeds/wilted leaves, as in many Rosaceae). Pruning stimulates the red new growth. More frost-sensitive than other hedges — at higher CH elevations a sheltered location.','Host plant of fire blight (Erwinia amylovora) — notifiable in CH, planting sometimes restricted in fruit-growing protection zones. Frost protection needed above ~800 m.','Seeds/pips and wilting leaves (low levels of cyanogenic glycosides, typical of Rosaceae)','after bud break May-June (promotes red new growth)','f'),
('photinia_x_fraseri_red_robin','es','Ligeramente tóxica (prunasina en las semillas/hojas marchitas, como en muchas rosáceas). La poda estimula los brotes rojos. Más sensible a las heladas que otros setos — en altitudes de CH, ubicación resguardada.','Planta huésped del fuego bacteriano (Erwinia amylovora) — de declaración obligatoria en CH, plantación a veces restringida en zonas protegidas de fruticultura. Protección contra heladas necesaria por encima de ~800 m.','Semillas/pepitas y hojas marchitas (bajas cantidades de glucósidos cianogénicos, típico de las rosáceas)','tras la brotación mayo-junio (favorece los nuevos brotes rojos)','f'),
('photinia_x_fraseri_red_robin','fr','Légèrement toxique (prunasine dans les graines/feuilles fanées, comme beaucoup de Rosacées). La taille stimule les pousses rouges. Plus sensible au gel que d''autres haies — en altitude en CH, emplacement abrité.','Plante-hôte du feu bactérien (Erwinia amylovora) — soumise à déclaration obligatoire en CH, plantation parfois restreinte dans les zones protégées d''arboriculture fruitière. Protection contre le gel nécessaire au-dessus de ~800 m.','Graines/pépins et feuilles fanées (faibles teneurs en glycosides cyanogènes, typique des Rosacées)','après le débourrement mai-juin (favorise les nouvelles pousses rouges)','f'),
('photinia_x_fraseri_red_robin','it','Leggermente tossica (prunasina nei semi/foglie appassite, come molte Rosacee). La potatura stimola i germogli rossi. Più sensibile al gelo di altre siepi — alle quote elevate in CH, posizione riparata.','Pianta ospite del colpo di fuoco batterico (Erwinia amylovora) — soggetta a obbligo di notifica in CH, messa a dimora talvolta limitata nelle zone protette di frutticoltura. Protezione dal gelo necessaria oltre i ~800 m.','Semi/noccioli e foglie appassite (basse quantità di glicosidi cianogenici, tipico delle Rosacee)','dopo il germogliamento maggio-giugno (favorisce i nuovi germogli rossi)','f'),
('picea_abies','en','Shallow-rooted – prone to windthrow, do not plant too close to buildings/paths. The main species of Swiss forestry, susceptible to bark beetle under drought stress.','The most important forest tree in Switzerland, up to ~2000 m above sea level. Threatened by drought + bark beetle on the Central Plateau; site-appropriate in mountain forest.',NULL,'rarely necessary; if needed in late summer (August)','f'),
('picea_abies','es','Enraizamiento superficial – propensa al derribo por viento, no plantar demasiado cerca de edificios/caminos. Especie principal de la silvicultura suiza, susceptible al escarabajo de la corteza bajo estrés hídrico.','Árbol forestal más importante de Suiza, hasta ~2000 m s.n.m. Amenazado por la sequía + el escarabajo de la corteza en la Meseta; adecuado a la estación en el bosque de montaña.',NULL,'raramente necesaria; en su caso a finales de verano (agosto)','f'),
('picea_abies','fr','Enracinement superficiel – sensible au chablis, ne pas planter trop près des bâtiments/chemins. Essence principale de la sylviculture suisse, sensible au scolyte en cas de stress hydrique.','Essence forestière la plus importante de Suisse, jusqu''à ~2000 m d''altitude. Menacée par la sécheresse + le scolyte sur le Plateau ; adaptée à la station en forêt de montagne.',NULL,'rarement nécessaire ; le cas échéant fin d''été (août)','f'),
('picea_abies','it','Apparato radicale superficiale – soggetto a schianto da vento, non piantare troppo vicino a edifici/vialetti. Specie principale della selvicoltura svizzera, suscettibile al bostrico in caso di stress idrico.','Specie forestale più importante della Svizzera, fino a ~2000 m s.l.m. Minacciata da siccità + bostrico sull''Altopiano; idonea alla stazione nel bosco di montagna.',NULL,'raramente necessaria; eventualmente a fine estate (agosto)','f'),
('pinus_sylvestris','en','Tap-rooted – very storm-firm, low building risk, thrives on poor, dry sites. Full sun essential, tolerates no shading.','Typical of dry, warm pine forests (Valais, Chur Rhine Valley). Climate-resilient on dry sites; in Valais locally declining due to mistletoe + drought.',NULL,'rarely necessary; spring','f'),
('pinus_sylvestris','es','Raíz pivotante – muy resistente a las tormentas, bajo riesgo para los edificios, prospera en estaciones pobres y secas. Pleno sol imprescindible, no tolera la sombra.','Típico de los pinares secos y cálidos (Valais, valle del Rin grisón). Resiliente al clima en estaciones secas; en Valais en regresión local por el muérdago + la sequía.',NULL,'raramente necesaria; primavera','f'),
('pinus_sylvestris','fr','Racine pivotante – très résistant aux tempêtes, faible risque pour les bâtiments, prospère sur les stations pauvres et sèches. Plein soleil impératif, ne supporte pas l''ombrage.','Typique des pinèdes sèches et chaudes (Valais, vallée du Rhin grisonne). Résilient au climat sur les stations sèches ; en Valais localement en recul à cause du gui + de la sécheresse.',NULL,'rarement nécessaire ; printemps','f'),
('pinus_sylvestris','it','Radice fittonante – molto resistente alle tempeste, basso rischio per gli edifici, prospera su stazioni povere e aride. Pieno sole indispensabile, non tollera l''ombreggiamento.','Tipico delle pinete secche e calde (Vallese, valle del Reno grigionese). Resiliente al clima su stazioni aride; in Vallese localmente in regresso a causa del vischio + della siccità.',NULL,'raramente necessaria; primavera','f'),
('platanus_x_hispanica','en','Non-toxic. Note: the fine star-shaped hairs of the fruits and emerging leaves can cause eye and respiratory irritation (mechanical, not toxic) — so the ''mild'' rating in the input was an irritation, not a toxicity question; toxicologically non-toxic. Very strong, shallow root pressure — can damage pavements and foundations, keep a generous distance. Extremely tolerant of urban climate and pruning.','In Switzerland a common avenue and square tree in cities (urban-climate tree). Due to aggressive root pressure and final size, keep a large distance from buildings. Massaria monitoring on old trees (traffic safety).',NULL,'Winter (leafless); very pruning-tolerant (candelabra/roof pruning possible)','f'),
('platanus_x_hispanica','es','No tóxico. Nota: los finos pelos estrellados de los frutos y de las hojas en brotación pueden provocar irritaciones oculares y de las vías respiratorias (mecánicas, no tóxicas) — por eso la indicación «leve» del input era una cuestión de irritación, no de toxicidad; toxicológicamente no tóxico. Presión radicular muy fuerte y superficial — puede dañar pavimentos y cimientos, mantener una distancia amplia. Extremadamente tolerante al clima urbano y a la poda.','En Suiza, árbol de avenida y de plaza frecuente en las ciudades (árbol de clima urbano). Debido a la agresiva presión radicular y al tamaño final, mantener una gran distancia de los edificios. Monitoreo de Massaria en árboles viejos (seguridad vial).',NULL,'Invierno (sin hojas); muy tolerante a la poda (posible poda en candelabro/en techo)','f'),
('platanus_x_hispanica','fr','Non toxique. Remarque : les fins poils étoilés des fruits et des feuilles en débourrement peuvent provoquer des irritations des yeux et des voies respiratoires (mécaniques, non toxiques) — la mention « légère » dans la saisie concernait donc une question d''irritation, pas de toxicité ; sur le plan toxicologique, non toxique. Pression racinaire très forte et superficielle — peut endommager revêtements et fondations, garder une distance généreuse. Extrêmement tolérant au climat urbain et à la taille.','En Suisse, arbre d''alignement et de place fréquent en ville (arbre de climat urbain). En raison de la pression racinaire agressive et de la taille adulte, respecter une grande distance aux bâtiments. Surveillance du Massaria sur les arbres âgés (sécurité routière).',NULL,'Hiver (sans feuilles) ; très tolérant à la taille (taille en candélabre/en toit possible)','f'),
('platanus_x_hispanica','it','Non tossico. Nota: i fini peli stellati dei frutti e delle foglie in germogliamento possono provocare irritazioni a occhi e vie respiratorie (meccaniche, non tossiche) — la dicitura «lieve» nell''input riguardava quindi un''irritazione, non la tossicità; dal punto di vista tossicologico è non tossico. Pressione radicale molto forte e superficiale — può danneggiare pavimentazioni e fondazioni, mantenere una distanza ampia. Estremamente tollerante al clima urbano e alla potatura.','In Svizzera frequente albero da viale e da piazza nelle città (albero da clima urbano). A causa dell''aggressiva pressione radicale e delle dimensioni finali, mantenere una grande distanza dagli edifici. Monitoraggio della Massaria sugli alberi vecchi (sicurezza stradale).',NULL,'Inverno (senza foglie); molto tollerante alla potatura (possibile potatura a candelabro/a tetto)','f'),
('populus_nigra_italica','en','Non-toxic. ROOT WARNING: aggressive, far-spreading shallow roots searching for water — can severely damage drainage, sewer pipes, foundations and pavements. Minimum distance of 12 m from buildings/lines. Fast-growing but short-lived and prone to wind breakage (branches). Only for large, open areas.','Classic clone of the Italian/Ticino avenues, up to ~1000 m. In Switzerland to be planted only at a large distance from infrastructure due to root damage and wind breakage. Male clone — no troublesome poplar fluff.',NULL,'Winter (leafless); pruning-tolerant','f'),
('populus_nigra_italica','es','No tóxico. ADVERTENCIA raíces: raíces superficiales agresivas que se extienden lejos en busca de agua — pueden dañar gravemente drenajes, tuberías de alcantarillado, cimientos y pavimentos. Distancia mínima de 12 m a edificios/conducciones. De crecimiento rápido pero de vida corta y propenso a la rotura por viento (ramas). Solo para grandes superficies despejadas.','Clon clásico de las avenidas italianas/tesinesas, hasta ~1000 m. En Suiza, plantar solo a gran distancia de las infraestructuras debido a los daños radiculares y la rotura por viento. Clon masculino — sin molesta pelusa de álamo.',NULL,'Invierno (sin hojas); tolerante a la poda','f'),
('populus_nigra_italica','fr','Non toxique. AVERTISSEMENT racines : racines superficielles agressives, s''étalant loin à la recherche d''eau — peuvent gravement endommager drainages, canalisations d''égout, fondations et revêtements. Distance minimale de 12 m aux bâtiments/conduites. À croissance rapide mais à vie courte et sensible au bris par le vent (branches). Uniquement pour de grandes surfaces dégagées.','Clone classique des allées italiennes/tessinoises, jusqu''à ~1000 m. En Suisse, à planter uniquement à grande distance des infrastructures en raison des dégâts racinaires et du bris par le vent. Clone mâle — pas de duvet de peuplier gênant.',NULL,'Hiver (sans feuilles) ; tolérant à la taille','f'),
('populus_nigra_italica','it','Non tossico. AVVERTENZA radici: radici superficiali aggressive, estese a grande distanza in cerca d''acqua — possono danneggiare gravemente drenaggi, tubazioni fognarie, fondazioni e pavimentazioni. Distanza minima di 12 m da edifici/condotte. A crescita rapida ma di breve durata e soggetto a rottura da vento (rami). Solo per grandi superfici libere.','Clone classico dei viali italiani/ticinesi, fino a ~1000 m. In Svizzera da piantare solo a grande distanza dalle infrastrutture a causa dei danni radicali e della rottura da vento. Clone maschile — niente fastidioso pappo di pioppo.',NULL,'Inverno (senza foglie); tollerante alla potatura','f'),
('prunus_armeniaca','en','Very early flowering → susceptible to late frost, hence a warm, sheltered south-facing position (gladly espaliered against a house wall). Apricot kernels have a high cyanide content — dangerous for children/pets. Susceptible to brown rot (Monilia) and apoplexy (shoot dieback).','Valais is Switzerland''s core apricot region (Luizet variety). Late-frost risk limits cultivation at higher/colder sites. Bitter wild-apricot kernels are strongly cyanogenic.','The stone kernels contain especially high amygdalin (high hydrocyanic acid release), as do bark/leaves; the flesh is edible','after the harvest (summer) to avoid gummosis and brown rot; never in winter/frost','f'),
('prunus_armeniaca','es','Floración muy temprana → sensible a las heladas tardías, por ello una exposición sur cálida y resguardada (de buen grado en espaldera contra un muro de la casa). Los huesos de albaricoque tienen un alto contenido de cianuro — peligrosos para niños/mascotas. Sensible a la monilia y a la apoplejía (muerte de los brotes).','El Valais es la región central suiza del albaricoque (variedad Luizet). El riesgo de heladas tardías limita el cultivo en sitios más altos/fríos. Los huesos amargos del albaricoque silvestre son fuertemente cianogénicos.','Los huesos contienen especialmente mucha amigdalina (alta liberación de ácido cianhídrico), al igual que la corteza/las hojas; la pulpa es comestible','tras la cosecha (verano) para evitar la gomosis y la monilia; nunca en invierno/con helada','f'),
('prunus_armeniaca','fr','Floraison très précoce → sensible aux gelées tardives, d''où une exposition sud chaude et abritée (volontiers en espalier contre un mur de maison). Les noyaux d''abricot ont une forte teneur en cyanure — dangereux pour les enfants/animaux domestiques. Sensible à la moniliose et à l''apoplexie (dépérissement des rameaux).','Le Valais est la région centrale suisse de l''abricot (variété Luizet). Le risque de gel tardif limite la culture dans les sites plus élevés/froids. Les noyaux amers d''abricot sauvage sont fortement cyanogènes.','Les noyaux contiennent particulièrement beaucoup d''amygdaline (forte libération d''acide cyanhydrique), de même que l''écorce/les feuilles ; la pulpe est comestible','après la récolte (été) pour éviter l''écoulement de gomme et la moniliose ; jamais en hiver/au gel','f'),
('prunus_armeniaca','it','Fioritura molto precoce → sensibile alle gelate tardive, quindi esposizione sud calda e riparata (volentieri a spalliera contro un muro di casa). I noccioli di albicocca hanno un elevato contenuto di cianuro — pericolosi per bambini/animali domestici. Sensibile alla monilia e all''apoplessia (deperimento dei rami).','Il Vallese è la regione centrale svizzera dell''albicocca (varietà Luizet). Il rischio di gelo tardivo limita la coltivazione nelle località più alte/fredde. I noccioli amari di albicocca selvatica sono fortemente cianogeni.','I noccioli contengono particolarmente molta amigdalina (forte rilascio di acido cianidrico), oltre a corteccia/foglie; la polpa è commestibile','dopo la raccolta (estate) per evitare la fuoriuscita di gomma e la monilia; mai in inverno/con il gelo','f'),
('prunus_avium','en','Vigorous large tree (wild form = wild cherry/forest tree). Wilting foliage and stone kernels are dangerous for grazing/domestic animals. Sensitive to pruning wounds (gummosis, brown rot). Choose a generous planting distance.','Wild cherry is a native forest and landscape tree (Plateau standard-trunk cherry orchards, e.g. Basel-Country/Fricktal). As a wild tree up to 25 m. Kernels and wilted foliage are toxic for livestock.','Seeds (stone kernels), bark and fresh/wilting leaves contain cyanogenic glycosides (prunasin, amygdalin) → hydrocyanic acid; the flesh is edible','directly after the harvest (June-August) to avoid gummosis; never in frost','f'),
('prunus_avium','es','Árbol grande vigoroso (forma silvestre = cerezo silvestre/árbol forestal). El follaje marchito y los huesos son peligrosos para el ganado/los animales domésticos. Sensible a las heridas de poda (gomosis, monilia). Elegir una distancia de plantación amplia.','El cerezo silvestre es un árbol forestal y paisajístico autóctono (cultivos de cerezos de tronco alto de la Meseta, p. ej. Basilea-Campiña/Fricktal). Como árbol silvestre hasta 25 m. Los huesos y el follaje marchito son tóxicos para el ganado.','Las semillas (huesos), la corteza y las hojas frescas/marchitas contienen glucósidos cianogénicos (prunasina, amigdalina) → ácido cianhídrico; la pulpa es comestible','directamente tras la cosecha (junio-agosto) para evitar la gomosis; nunca con helada','f'),
('prunus_avium','fr','Grand arbre vigoureux (forme sauvage = merisier/arbre forestier). Le feuillage flétrissant et les noyaux sont dangereux pour le bétail/les animaux domestiques. Sensible aux blessures de taille (écoulement de gomme, moniliose). Choisir une distance de plantation généreuse.','Le merisier est un arbre forestier et paysager indigène (cultures de cerisiers haute-tige du Plateau, p. ex. Bâle-Campagne/Fricktal). En arbre sauvage jusqu''à 25 m. Les noyaux et le feuillage flétri sont toxiques pour le bétail.','Les graines (noyaux), l''écorce et les feuilles fraîches/flétrissantes contiennent des glycosides cyanogènes (prunasine, amygdaline) → acide cyanhydrique ; la pulpe est comestible','directement après la récolte (juin-août) pour éviter l''écoulement de gomme ; jamais au gel','f'),
('prunus_avium','it','Grande albero vigoroso (forma selvatica = ciliegio selvatico/albero forestale). Il fogliame appassito e i noccioli sono pericolosi per il bestiame/gli animali domestici. Sensibile alle ferite da potatura (fuoriuscita di gomma, monilia). Scegliere una distanza di impianto ampia.','Il ciliegio selvatico è un albero forestale e paesaggistico indigeno (colture di ciliegi ad alto fusto dell''Altopiano, p. es. Basilea Campagna/Fricktal). Come albero selvatico fino a 25 m. I noccioli e il fogliame appassito sono tossici per il bestiame.','I semi (noccioli), la corteccia e le foglie fresche/appassite contengono glicosidi cianogeni (prunasina, amigdalina) → acido cianidrico; la polpa è commestibile','direttamente dopo la raccolta (giugno-agosto) per evitare la fuoriuscita di gomma; mai con il gelo','f'),
('prunus_cerasifera_nigra','en','Early and strikingly pink flowering, dark-red foliage. Small edible plum fruits (flesh non-toxic), but leaves/kernels cyanogenic. Wilted foliage is especially dangerous for grazing animals/horses. Prune sparingly because of gummosis.','In Switzerland a very common front-garden/street tree. Cyanogenic glycosides in leaves/kernels — tox.ch lists Prunus as mildly toxic; do not put wilted foliage in animal pastures.','Leaves, bark, kernels/stones (cyanogenic glycosides, especially in wilted foliage)','after flowering (May/June), in dry weather; prune Prunus as little as possible','f'),
('prunus_cerasifera_nigra','es','Floración temprana y rosa llamativa, follaje rojo oscuro. Pequeños frutos de ciruela comestibles (pulpa no tóxica), pero hojas/huesos cianogénicos. El follaje marchito es especialmente peligroso para el ganado/los caballos. Podar con moderación debido a la gomosis.','En Suiza, árbol de antejardín/de calle muy frecuente. Glucósidos cianogénicos en hojas/huesos — tox.ch clasifica el Prunus como ligeramente tóxico; no poner el follaje marchito en los pastos de animales.','Hojas, corteza, huesos/piedras (glucósidos cianogénicos, sobre todo en el follaje marchito)','tras la floración (mayo/junio), con tiempo seco; podar el Prunus lo menos posible','f'),
('prunus_cerasifera_nigra','fr','Floraison précoce et rose remarquable, feuillage rouge foncé. Petits fruits de prune comestibles (pulpe non toxique), mais feuilles/noyaux cyanogènes. Le feuillage flétri est particulièrement dangereux pour le bétail/les chevaux. Taille parcimonieuse à cause de l''écoulement de gomme.','En Suisse, arbre de jardinet/de rue très fréquent. Glycosides cyanogènes dans les feuilles/noyaux — tox.ch classe Prunus comme légèrement toxique ; ne pas mettre le feuillage flétri dans les pâturages d''animaux.','Feuilles, écorce, noyaux/pierres (glycosides cyanogènes, surtout dans le feuillage flétri)','après la floraison (mai/juin), par temps sec ; tailler le Prunus le moins possible','f'),
('prunus_cerasifera_nigra','it','Fioritura precoce e rosa vistosa, fogliame rosso scuro. Piccoli frutti di susina commestibili (polpa non tossica), ma foglie/noccioli cianogeni. Il fogliame appassito è particolarmente pericoloso per il bestiame/i cavalli. Potatura parsimoniosa a causa della fuoriuscita di gomma.','In Svizzera, albero da giardinetto/da strada molto frequente. Glicosidi cianogeni in foglie/noccioli — tox.ch classifica il Prunus come leggermente tossico; non mettere il fogliame appassito nei pascoli degli animali.','Foglie, corteccia, noccioli/pietre (glicosidi cianogeni, soprattutto nel fogliame appassito)','dopo la fioritura (maggio/giugno), con tempo asciutto; potare il Prunus il meno possibile','f'),
('prunus_cerasus','en','Mostly self-fertile (e.g. Schattenmorelle/Morello cherry), a good choice for a solitary tree. Bears on one-year-old wood, hence consistent rejuvenation pruning. Kernels/foliage toxic for pets.','More robust and frost-hardier than sweet cherry, also productive at higher altitudes. The Morello (Schattenmorelle) is widespread in Swiss home gardens.','Stone kernels, bark and leaves with cyanogenic glycosides; the flesh is edible','after the harvest (summer); regularly thin out old fruiting wood','f'),
('prunus_cerasus','es','En su mayoría autofértil (p. ej. Schattenmorelle/guinda), buena elección para un árbol aislado. Fructifica en la madera de un año, de ahí una poda de rejuvenecimiento sistemática. Huesos/follaje tóxicos para las mascotas.','Más robusto y más resistente al frío que el cerezo dulce, productivo también en altitud. La guinda (Schattenmorelle) está muy extendida en los jardines suizos.','Huesos, corteza y hojas con glucósidos cianogénicos; la pulpa es comestible','tras la cosecha (verano); aclarar regularmente la vieja madera fructífera','f'),
('prunus_cerasus','fr','Le plus souvent autofertile (p. ex. Schattenmorelle/griotte du Nord), bon choix pour un arbre isolé. Fructifie sur le bois d''un an, d''où une taille de rajeunissement systématique. Noyaux/feuillage toxiques pour les animaux domestiques.','Plus robuste et plus résistant au gel que le cerisier doux, productif aussi en altitude. La griotte du Nord (Schattenmorelle) est largement répandue dans les jardins suisses.','Noyaux, écorce et feuilles avec glycosides cyanogènes ; la pulpe est comestible','après la récolte (été) ; éclaircir régulièrement le vieux bois fructifère','f'),
('prunus_cerasus','it','Per lo più autofertile (p. es. Schattenmorelle/amarena), buona scelta per un albero isolato. Fruttifica sul legno di un anno, quindi una potatura di ringiovanimento sistematica. Noccioli/fogliame tossici per gli animali domestici.','Più robusto e più resistente al gelo del ciliegio dolce, produttivo anche in quota. L''amarena (Schattenmorelle) è ampiamente diffusa nei giardini svizzeri.','Noccioli, corteccia e foglie con glicosidi cianogeni; la polpa è commestibile','dopo la raccolta (estate); diradare regolarmente il vecchio legno da frutto','f'),
('prunus_domestica_subsp_domestica','en','Many varieties (e.g. damson/Hauszwetschge) self-fertile, yield is better with a pollinator. Susceptible to sharka (plum pox). Stone kernels/foliage toxic for pets.','The Hauszwetschge (damson) is a traditional Swiss standard-trunk tree (juice/schnapps). Sharka virus is regionally widespread, grub out affected trees. Kernels/wilted foliage toxic for livestock.','Stone kernels, bark and leaves contain cyanogenic glycosides; the flesh is edible','after the harvest / late summer (gummosis prevention); never in frost','f'),
('prunus_domestica_subsp_domestica','es','Muchas variedades (p. ej. ciruela damascena/Hauszwetschge) autofértiles, el rendimiento es mejor con un polinizador. Sensible a la sharka (viruela del ciruelo). Huesos/follaje tóxicos para las mascotas.','La Hauszwetschge (ciruela damascena) es un árbol de tronco alto tradicional suizo (zumo/aguardiente). El virus de la sharka está extendido regionalmente, arrancar los árboles afectados. Huesos/follaje marchito tóxicos para el ganado.','Los huesos, la corteza y las hojas contienen glucósidos cianogénicos; la pulpa es comestible','tras la cosecha / fin del verano (prevención de la gomosis); nunca con helada','f'),
('prunus_domestica_subsp_domestica','fr','Beaucoup de variétés (p. ex. quetsche commune/Hauszwetschge) autofertiles, rendement meilleur avec un pollinisateur. Sensible à la sharka (variole). Noyaux/feuillage toxiques pour les animaux domestiques.','La quetsche commune (Hauszwetschge) est un arbre haute-tige traditionnel suisse (jus de fruits/eau-de-vie). Le virus de la sharka est répandu régionalement, arracher les arbres atteints. Noyaux/feuillage flétri toxiques pour le bétail.','Les noyaux, l''écorce et les feuilles contiennent des glycosides cyanogènes ; la pulpe est comestible','après la récolte / fin d''été (prévention de l''écoulement de gomme) ; jamais au gel','f'),
('prunus_domestica_subsp_domestica','it','Molte varietà (p. es. susina domestica/Hauszwetschge) autofertili, resa migliore con un impollinatore. Sensibile alla sharka (vaiolatura). Noccioli/fogliame tossici per gli animali domestici.','La susina domestica (Hauszwetschge) è un albero ad alto fusto tradizionale svizzero (succo/acquavite). Il virus della sharka è diffuso a livello regionale, estirpare gli alberi colpiti. Noccioli/fogliame appassito tossici per il bestiame.','I noccioli, la corteccia e le foglie contengono glicosidi cianogeni; la polpa è commestibile','dopo la raccolta / fine estate (prevenzione della fuoriuscita di gomma); mai con il gelo','f'),
('prunus_domestica_subsp_syriaca','en','Mostly self-fertile, abundant yields of small yellow fruits. Heat-loving, prefer a sheltered position. Kernels/foliage toxic for pets.','In warmer Swiss locations (Plateau, Lake Geneva region, Ticino) it bears well. Self-fertile, ideal for a solitary tree in the home garden.','Stone kernels, bark and leaves with cyanogenic glycosides; the flesh is edible','after the harvest / late summer; never in frost','f'),
('prunus_domestica_subsp_syriaca','es','En su mayoría autofértil, rendimientos abundantes de pequeños frutos amarillos. Termófilo, preferir una exposición resguardada. Huesos/follaje tóxicos para las mascotas.','En las localidades suizas más cálidas (Meseta, región del lago Lemán, Tesino) fructifica bien. Autofértil, ideal para un árbol aislado en el jardín de casa.','Los huesos, la corteza y las hojas con glucósidos cianogénicos; la pulpa es comestible','tras la cosecha / fin del verano; nunca con helada','f'),
('prunus_domestica_subsp_syriaca','fr','Le plus souvent autofertile, rendements abondants de petits fruits jaunes. Thermophile, préférer une exposition abritée. Noyaux/feuillage toxiques pour les animaux domestiques.','Dans les sites suisses plus chauds (Plateau, région lémanique, Tessin), bonne fructification. Autofertile, idéal pour un arbre isolé au jardin.','Les noyaux, l''écorce et les feuilles avec glycosides cyanogènes ; la pulpe est comestible','après la récolte / fin d''été ; jamais au gel','f'),
('prunus_domestica_subsp_syriaca','it','Per lo più autofertile, rese abbondanti di piccoli frutti gialli. Termofilo, preferire un''esposizione riparata. Noccioli/fogliame tossici per gli animali domestici.','Nelle località svizzere più calde (Altopiano, regione lemanica, Ticino) fruttifica bene. Autofertile, ideale per un albero isolato nel giardino di casa.','I noccioli, la corteccia e le foglie con glicosidi cianogeni; la polpa è commestibile','dopo la raccolta / fine estate; mai con il gelo','f'),
('prunus_laurocerasus','en','Strongly toxic: leaves/kernels release hydrocyanic acid (prunasin/amygdalin). The kernels of the black fruits are dangerous to children/dogs. Do not shred/compost prunings near animals. Classified as invasive in Switzerland — spread by birds.','On the Black List of invasive neophytes (Info Flora); sale/new planting prohibited in Switzerland since 09/2024. Strongly toxic — tox.ch, Tox Info Suisse 145.','Leaves and seeds/kernels (cyanogenic glycosides — hydrocyanic acid), flesh slightly','April-May and August (hand secateurs rather than hedge trimmer — otherwise brown cut edges)','f'),
('prunus_laurocerasus','es','Fuertemente tóxico: las hojas/los huesos liberan ácido cianhídrico (prunasina/amigdalina). Los huesos de los frutos negros son peligrosos para niños/perros. No triturar/compostar los restos de poda cerca de animales. Clasificado como invasor en Suiza — propagación por las aves.','En la Lista negra de neófitos invasores (Info Flora); venta/nueva plantación prohibidas en Suiza desde 09/2024. Fuertemente tóxico — tox.ch, Tox Info Suisse 145.','Hojas y semillas/huesos (glucósidos cianogénicos — ácido cianhídrico), pulpa en escasa medida','abril-mayo y agosto (tijeras de mano en lugar de cortasetos — de lo contrario bordes de corte marrones)','f'),
('prunus_laurocerasus','fr','Fortement toxique : les feuilles/noyaux libèrent de l''acide cyanhydrique (prunasine/amygdaline). Les noyaux des fruits noirs sont dangereux pour les enfants/chiens. Ne pas broyer/composter les déchets de taille à proximité d''animaux. Classé invasif en Suisse — propagation par les oiseaux.','Sur la Liste noire des néophytes envahissants (Info Flora) ; vente/nouvelle plantation interdites en Suisse depuis 09/2024. Fortement toxique — tox.ch, Tox Info Suisse 145.','Feuilles et graines/noyaux (glycosides cyanogènes — acide cyanhydrique), pulpe faiblement','avril-mai et août (sécateur à main plutôt que taille-haie — sinon bords de coupe bruns)','f'),
('prunus_laurocerasus','it','Fortemente tossico: le foglie/i noccioli liberano acido cianidrico (prunasina/amigdalina). I noccioli dei frutti neri sono pericolosi per bambini/cani. Non triturare/compostare gli scarti di potatura vicino agli animali. Classificato invasivo in Svizzera — diffusione tramite uccelli.','Sulla Lista nera dei neofiti invasivi (Info Flora); vendita/nuovo impianto vietati in Svizzera da 09/2024. Fortemente tossico — tox.ch, Tox Info Suisse 145.','Foglie e semi/noccioli (glicosidi cianogeni — acido cianidrico), polpa in misura ridotta','aprile-maggio e agosto (forbici a mano anziché tagliasiepi — altrimenti bordi di taglio marroni)','f'),
('prunus_persica','en','Self-fertile, fast-growing but short-lived. Very susceptible to peach leaf curl (Taphrina) — choose an airy site with rain protection. Short-lived (often only 10-15 productive years). Kernels/foliage toxic for pets.','Reliable only in the warmest Swiss locations (Ticino, Valais, Lake Geneva region, urban climate). Peach leaf curl is the limiting factor; the vineyard peach (red-fleshed) is traditionally widespread.','Stone kernels, bark and leaves contain cyanogenic glycosides; the flesh is edible','in spring after bud break until shortly after flowering; bears on the previous year''s wood','f'),
('prunus_persica','es','Autofértil, de crecimiento rápido pero de vida corta. Muy sensible a la lepra del melocotonero (Taphrina) — elegir un emplazamiento aireado con protección contra la lluvia. De vida corta (a menudo solo 10-15 años productivos). Huesos/follaje tóxicos para las mascotas.','Fiable solo en las localidades suizas más cálidas (Tesino, Valais, región del lago Lemán, clima urbano). La lepra del melocotonero es el factor limitante; el melocotón de viña (de pulpa roja) está tradicionalmente extendido.','Los huesos, la corteza y las hojas contienen glucósidos cianogénicos; la pulpa es comestible','en primavera tras la brotación hasta poco después de la floración; fructifica en la madera del año anterior','f'),
('prunus_persica','fr','Autofertile, à croissance rapide mais à vie courte. Très sensible à la cloque du pêcher (Taphrina) — choisir un emplacement aéré avec protection contre la pluie. À vie courte (souvent seulement 10-15 années productives). Noyaux/feuillage toxiques pour les animaux domestiques.','Fiable uniquement dans les sites suisses les plus chauds (Tessin, Valais, région lémanique, climat urbain). La cloque du pêcher est un facteur limitant ; la pêche de vigne (à chair rouge) est traditionnellement répandue.','Les noyaux, l''écorce et les feuilles contiennent des glycosides cyanogènes ; la pulpe est comestible','au printemps après le débourrement jusqu''à peu après la floraison ; fructifie sur le bois de l''année précédente','f'),
('prunus_persica','it','Autofertile, a crescita rapida ma di breve durata. Molto sensibile al bolla del pesco (Taphrina) — scegliere una posizione ariosa con protezione dalla pioggia. Di breve durata (spesso solo 10-15 anni produttivi). Noccioli/fogliame tossici per gli animali domestici.','Affidabile solo nelle località svizzere più calde (Ticino, Vallese, regione lemanica, clima urbano). Il bolla del pesco è il fattore limitante; la pesca di vigna (a polpa rossa) è tradizionalmente diffusa.','I noccioli, la corteccia e le foglie contengono glicosidi cianogeni; la polpa è commestibile','in primavera dopo il germogliamento fino a poco dopo la fioritura; fruttifica sul legno dell''anno precedente','f'),
('prunus_persica_var_nucipersica','en','Smooth-skinned mutation of the peach, self-fertile. Just as susceptible to leaf curl as the peach, slightly more heat-demanding. Stones/foliage toxic to pets.','Like the peach, reliable only in the warmest Swiss locations (Ticino, Valais). Wall espalier in a sheltered south-facing position recommended.','Stones, bark and leaves contain cyanogenic glycosides; the flesh of the fruit is edible','Spring after bud break until shortly after flowering; bears on the previous year''s wood','f'),
('prunus_persica_var_nucipersica','es','Mutación de piel lisa del melocotonero, autofértil. Igual de sensible a la lepra que el melocotonero, algo más exigente en calor. Huesos/follaje tóxicos para las mascotas.','Como el melocotonero, fiable solo en las ubicaciones más cálidas de Suiza (Tesino, Valais). Se recomienda espaldera en pared en exposición sur protegida.','Los huesos, la corteza y las hojas contienen glucósidos cianogénicos; la pulpa del fruto es comestible','Primavera tras la brotación hasta poco después de la floración; fructifica en la madera del año anterior','f'),
('prunus_persica_var_nucipersica','fr','Mutation à peau lisse du pêcher, autofertile. Aussi sensible à la cloque que le pêcher, un peu plus exigeante en chaleur. Noyaux/feuillage toxiques pour les animaux domestiques.','Comme le pêcher, fiable seulement dans les situations les plus chaudes de Suisse (Tessin, Valais). Espalier mural en exposition sud abritée recommandé.','Les noyaux, l''écorce et les feuilles contiennent des glycosides cyanogènes; la chair du fruit est comestible','Printemps après le débourrement jusqu''à peu après la floraison; fructifie sur le bois de l''année précédente','f'),
('prunus_persica_var_nucipersica','it','Mutazione a buccia liscia del pesco, autofertile. Sensibile alla bolla come il pesco, un po'' più esigente in calore. Noccioli/fogliame tossici per gli animali domestici.','Come il pesco, affidabile solo nelle posizioni più calde della Svizzera (Ticino, Vallese). Consigliata la spalliera a muro in posizione sud riparata.','Noccioli, corteccia e foglie contengono glicosidi cianogenici; la polpa del frutto è commestibile','Primavera dopo il germogliamento fino a poco dopo la fioritura; fruttifica sul legno dell''anno precedente','f'),
('prunus_serrulata','en','Ornamental tree, no edible fruit. Susceptible to shot-hole disease and brown rot (Monilia). Prune only in dry weather, keep wounds clean. Grafted – remove wild shoots below the graft union.','Widespread in Switzerland as an avenue and front-garden tree; cyanogenic glycosides in leaves/stones – tox.ch lists Prunus species as mildly toxic. Do not let children swallow the stones.','Leaves, bark, seeds/stones (cyanogenic glycosides)','directly after flowering (May/June); prune Prunus as little as possible due to gummosis/risk of infection','f'),
('prunus_serrulata','es','Árbol ornamental, sin frutos comestibles. Sensible al cribado y a la monilia. Podar solo con tiempo seco, mantener las heridas limpias. Injertado – eliminar los brotes silvestres por debajo del punto de injerto.','Muy extendido en Suiza como árbol de alineación y de jardín delantero; glucósidos cianogénicos en hojas/huesos – tox.ch clasifica las especies de Prunus como ligeramente tóxicas. No dejar que los niños traguen los huesos.','Hojas, corteza, semillas/huesos (glucósidos cianogénicos)','directamente después de la floración (mayo/junio); podar los Prunus lo menos posible debido a la gomosis/riesgo de infección','f'),
('prunus_serrulata','fr','Arbre d''ornement, pas de fruits comestibles. Sensible à la criblure et à la moniliose. Tailler uniquement par temps sec, garder les plaies propres. Greffé – éliminer les rejets sauvages sous le point de greffe.','Très répandu en Suisse comme arbre d''alignement et de jardin de devant; glycosides cyanogènes dans les feuilles/noyaux – tox.ch classe les espèces de Prunus comme légèrement toxiques. Ne pas laisser les enfants avaler les noyaux.','Feuilles, écorce, graines/noyaux (glycosides cyanogènes)','directement après la floraison (mai/juin); tailler le moins possible les Prunus en raison du flux gommeux/risque d''infection','f'),
('prunus_serrulata','it','Albero ornamentale, senza frutti commestibili. Sensibile al corineo e alla moniliosi. Potare solo con tempo asciutto, mantenere pulite le ferite. Innestato – rimuovere i polloni selvatici sotto il punto d''innesto.','Molto diffuso in Svizzera come albero da viale e da giardino antistante; glicosidi cianogenici nelle foglie/noccioli – tox.ch classifica le specie di Prunus come leggermente tossiche. Non lasciare che i bambini ingoino i noccioli.','Foglie, corteccia, semi/noccioli (glicosidi cianogenici)','subito dopo la fioritura (maggio/giugno); potare il meno possibile i Prunus a causa del flusso gommoso/rischio d''infezione','f'),
('prunus_spinosa','en','Forms strong root suckers - can spread invasively, consider a rhizome barrier in small gardens. Early bee forage, caterpillar food plant. Ripe sloes are only edible after frost.','Native, ecologically valuable (butterfly food plant). Beware of sucker formation - not directly at property boundaries without a barrier.','Seeds/stones and leaves contain cyanogenic glycosides (amygdalin); the flesh of the ripe sloe is edible','after flowering or in late winter; remove root suckers regularly','f'),
('prunus_spinosa','es','Forma fuertes brotes radiculares - puede extenderse de forma invasiva, considerar una barrera antirrizoma en jardines pequeños. Planta melífera temprana, planta nutricia para orugas. Las endrinas maduras solo son comestibles tras la helada.','Autóctona, ecológicamente valiosa (planta nutricia de mariposas). Atención a la formación de brotes - no directamente en los límites de la propiedad sin barrera.','Las semillas/huesos y las hojas contienen glucósidos cianogénicos (amigdalina); la pulpa de la endrina madura es comestible','después de la floración o a finales de invierno; eliminar regularmente los brotes radiculares','f'),
('prunus_spinosa','fr','Forme de forts drageons racinaires - peut s''étendre de façon invasive, envisager une barrière anti-rhizome dans les petits jardins. Plante mellifère précoce, plante nourricière pour chenilles. Les prunelles mûres ne sont consommables qu''après le gel.','Indigène, écologiquement précieuse (plante nourricière de papillons). Attention à la formation de drageons - pas directement aux limites de propriété sans barrière.','Les graines/noyaux et les feuilles contiennent des glycosides cyanogènes (amygdaline); la chair de la prunelle mûre est comestible','après la floraison ou en fin d''hiver; éliminer régulièrement les drageons racinaires','f'),
('prunus_spinosa','it','Forma forti polloni radicali - può diffondersi in modo invasivo, valutare una barriera antirizoma nei giardini piccoli. Pianta mellifera precoce, pianta nutrice per bruchi. Le prugnole mature sono commestibili solo dopo il gelo.','Indigena, ecologicamente preziosa (pianta nutrice di farfalle). Attenzione alla formazione di polloni - non direttamente ai confini di proprietà senza barriera.','Semi/noccioli e foglie contengono glicosidi cianogenici (amigdalina); la polpa della prugnola matura è commestibile','dopo la fioritura o a fine inverno; rimuovere regolarmente i polloni radicali','f'),
('pseudotsuga_menziesii','en','Introduced North American tree species, fast-growing and more storm-stable than spruce (heart-rooter). Fresh shoot with a lemony scent. Frost-sensitive during bud break (avoid late-frost sites).','Important introduced forestry species, regarded as a climate-resilient spruce alternative on the Swiss Plateau. Used in a locally controlled manner due to the invasiveness debate.',NULL,'rarely necessary; late summer','f'),
('pseudotsuga_menziesii','es','Especie arbórea norteamericana introducida, de crecimiento rápido y más resistente a las tormentas que la pícea (raíz en corazón). Brote fresco con aroma a limón. Sensible a las heladas durante la brotación (evitar zonas con heladas tardías).','Importante especie forestal introducida, considerada una alternativa a la pícea resiliente al clima en la Meseta suiza. Se emplea de forma localmente controlada debido al debate sobre su carácter invasor.',NULL,'raramente necesaria; finales de verano','f'),
('pseudotsuga_menziesii','fr','Essence nord-américaine introduite, à croissance rapide et plus résistante aux tempêtes que l''épicéa (racine en cœur). Jeune pousse au parfum citronné. Sensible au gel au débourrement (éviter les zones à gelées tardives).','Essence forestière introduite importante, considérée comme une alternative à l''épicéa résiliente au climat sur le Plateau. Utilisée de manière localement contrôlée en raison du débat sur son caractère invasif.',NULL,'rarement nécessaire; fin d''été','f'),
('pseudotsuga_menziesii','it','Specie arborea nordamericana introdotta, a crescita rapida e più resistente alle tempeste dell''abete rosso (radice a cuore). Giovane germoglio dal profumo di limone. Sensibile al gelo durante il germogliamento (evitare zone con gelate tardive).','Importante specie forestale introdotta, considerata un''alternativa all''abete rosso resiliente al clima sull''Altopiano. Impiegata in modo localmente controllato a causa del dibattito sull''invasività.',NULL,'raramente necessaria; fine estate','f'),
('pyrus_communis','en','Deep-rooting with a taproot tendency, hence a somewhat greater distance to buildings. Less vigorous on quince rootstock. Susceptible to fireblight.','Perry pears (e.g. Wässerwasser) are traditional in Swiss standard-tree orchards. Pear trellis rust is intensified by neighbouring junipers (host alternation). Fireblight is notifiable.','The seeds (pips) contain cyanogenic glycosides; the flesh of the fruit is edible','winter (February-March); the pear tolerates less severe pruning than the apple','f'),
('pyrus_communis','es','Enraizamiento profundo con tendencia a raíz pivotante, de ahí una distancia algo mayor a los edificios. Menos vigoroso sobre patrón de membrillero. Sensible al fuego bacteriano.','Las peras de sidra (p. ej. Wässerwasser) son tradicionales en los cultivos suizos de pie alto. La roya reticulada del peral se ve agravada por la vecindad de enebros (alternancia de huéspedes). El fuego bacteriano es de declaración obligatoria.','Las semillas (pepitas) contienen glucósidos cianogénicos; la pulpa del fruto es comestible','invierno (febrero-marzo); el peral tolera una poda menos severa que el manzano','f'),
('pyrus_communis','fr','Enracinement profond à tendance pivotante, d''où une distance un peu plus grande aux bâtiments. Moins vigoureux sur porte-greffe de cognassier. Sensible au feu bactérien.','Les poires à cidre (p. ex. Wässerwasser) traditionnelles dans les cultures suisses de hautes-tiges. La rouille grillagée du poirier est aggravée par le voisinage de genévriers (alternance d''hôtes). Le feu bactérien est à déclaration obligatoire.','Les graines (pépins) contiennent des glycosides cyanogènes; la chair du fruit est comestible','hiver (février-mars); le poirier supporte une taille moins sévère que le pommier','f'),
('pyrus_communis','it','Radicazione profonda con tendenza al fittone, quindi una distanza un po'' maggiore dagli edifici. Meno vigoroso su portinnesto di cotogno. Sensibile al colpo di fuoco batterico.','Le pere da sidro (ad es. Wässerwasser) tradizionali nelle colture svizzere ad alto fusto. La ruggine reticolata del pero è aggravata dalla vicinanza di ginepri (alternanza di ospiti). Il colpo di fuoco batterico è soggetto a notifica obbligatoria.','I semi (vinaccioli) contengono glicosidi cianogenici; la polpa del frutto è commestibile','inverno (febbraio-marzo); il pero sopporta una potatura meno severa del melo','f'),
('quercus_robur','en','Acorns and young leaves contain tannins — raw and in larger amounts they are harmful to humans, dogs and especially grazing livestock (cattle/horses: acorn poisoning). Child safety: do not eat raw acorns. Deep taproot — foundation-friendly, but very long-lived and large, only for large plots.','Native oak of Switzerland up to ~1000 m, mainly lowlands/floodplains. Beware of the oak processionary moth (health hazard from urticating hairs). Acorns are toxic to grazing livestock and dogs.','Acorns, young leaves and buds (tannins); raw in quantity they are toxic','summer (July/August) in leafed state; deadwood year-round','f'),
('quercus_robur','es','Las bellotas y las hojas jóvenes contienen taninos — crudas y en mayor cantidad son nocivas para las personas, los perros y especialmente el ganado de pasto (vacuno/caballos: intoxicación por bellotas). Seguridad infantil: no consumir bellotas crudas. Raíz pivotante profunda — respetuosa con los cimientos, pero muy longeva y grande, solo para parcelas grandes.','Roble autóctono de Suiza hasta ~1000 m, sobre todo en tierras bajas/zonas aluviales. Atención a la procesionaria del roble (peligro sanitario por los pelos urticantes). Las bellotas son tóxicas para el ganado de pasto y los perros.','Bellotas, hojas jóvenes y yemas (taninos); crudas en cantidad son tóxicas','verano (julio/agosto) en estado foliado; madera muerta todo el año','f'),
('quercus_robur','fr','Les glands et les jeunes feuilles contiennent des tanins — crus et en grande quantité, ils sont nocifs pour l''homme, les chiens et surtout le bétail (bovins/chevaux: intoxication aux glands). Sécurité des enfants: ne pas consommer de glands crus. Racine pivotante profonde — respectueuse des fondations, mais très longévive et grande, réservée aux grands terrains.','Chêne indigène de Suisse jusqu''à ~1000 m, surtout basses altitudes/zones alluviales. Attention à la processionnaire du chêne (danger sanitaire dû aux poils urticants). Les glands sont toxiques pour le bétail et les chiens.','Glands, jeunes feuilles et bourgeons (tanins); crus en quantité ils sont toxiques','été (juillet/août) à l''état feuillé; bois mort toute l''année','f'),
('quercus_robur','it','Le ghiande e le foglie giovani contengono tannini — crude e in grande quantità sono nocive per l''uomo, i cani e soprattutto il bestiame da pascolo (bovini/cavalli: intossicazione da ghiande). Sicurezza dei bambini: non consumare ghiande crude. Radice fittonante profonda — rispettosa delle fondamenta, ma molto longeva e grande, solo per grandi terreni.','Quercia indigena della Svizzera fino a ~1000 m, soprattutto basse quote/zone golenali. Attenzione alla processionaria della quercia (pericolo sanitario dovuto ai peli urticanti). Le ghiande sono tossiche per il bestiame e i cani.','Ghiande, foglie giovani e gemme (tannini); crude in quantità sono tossiche','estate (luglio/agosto) allo stato fogliato; legno morto tutto l''anno','f'),
('ribes_nigrum','en','Bears mainly on one-year-old wood – remove old wood annually, encourage young shoots. Higher nutrient and water requirement than the red currant. Aromatic, vitamin-C-rich berries.','Widespread in Switzerland as cassis, safe for children and pets. The gall mite is the main problem – choose resistant varieties. Up to ~1400 m.',NULL,'after harvest (bears on one-year-old wood)','f'),
('ribes_nigrum','es','Fructifica principalmente en la madera de un año – eliminar anualmente la madera vieja, favorecer los brotes jóvenes. Mayor necesidad de nutrientes y agua que la grosella roja. Bayas aromáticas, ricas en vitamina C.','Extendido en Suiza como casis, seguro para niños y mascotas. El ácaro de las yemas es el problema principal – elegir variedades resistentes. Hasta ~1400 m.',NULL,'después de la cosecha (fructifica en la madera de un año)','f'),
('ribes_nigrum','fr','Fructifie principalement sur le bois d''un an – éliminer chaque année le vieux bois, favoriser les jeunes pousses. Besoins en nutriments et en eau plus élevés que la groseille rouge. Baies aromatiques, riches en vitamine C.','Répandu en Suisse sous le nom de cassis, sans danger pour les enfants et les animaux domestiques. L''ériophyide est le problème principal – choisir des variétés résistantes. Jusqu''à ~1400 m.',NULL,'après la récolte (fructifie sur le bois d''un an)','f'),
('ribes_nigrum','it','Fruttifica prevalentemente sul legno di un anno – rimuovere annualmente il legno vecchio, favorire i germogli giovani. Maggiore fabbisogno di nutrienti e acqua rispetto al ribes rosso. Bacche aromatiche, ricche di vitamina C.','Diffuso in Svizzera come cassis, sicuro per bambini e animali domestici. L''eriofide è il problema principale – scegliere varietà resistenti. Fino a ~1400 m.',NULL,'dopo il raccolto (fruttifica sul legno di un anno)','f'),
('ribes_rubrum','en','Popular, undemanding berry shrub. Regular thinning cuts promote yield, as it bears on 2-3-year-old wood. Mulching keeps this shallow-rooter moist.','Widely grown home-garden berry shrub in Switzerland, child-friendly. Problem-free up to ~1400 m a.s.l. No root risk, can be planted close to buildings.',NULL,'after harvest / winter (thin out old wood)','f'),
('ribes_rubrum','es','Arbusto de bayas popular y poco exigente. Una poda de aclareo regular favorece el rendimiento, ya que fructifica en la madera de 2-3 años. El acolchado mantiene húmedo este sistema radicular superficial.','Arbusto de bayas de jardín doméstico muy extendido en Suiza, apto para niños. Sin problemas hasta ~1400 m s. n. m. Sin riesgo radicular, plantable cerca de edificios.',NULL,'después de la cosecha / invierno (aclarar la madera vieja)','f'),
('ribes_rubrum','fr','Arbuste à baies apprécié et peu exigeant. Une taille d''éclaircie régulière favorise le rendement, car il fructifie sur le bois de 2-3 ans. Le paillage maintient l''humidité de cet enracinement superficiel.','Arbuste à baies de jardin familial très répandu en Suisse, adapté aux enfants. Sans problème jusqu''à ~1400 m d''altitude. Pas de risque racinaire, plantable près des bâtiments.',NULL,'après la récolte / hiver (éclaircir le vieux bois)','f'),
('ribes_rubrum','it','Arbusto da bacche apprezzato e poco esigente. Un taglio di diradamento regolare favorisce la resa, poiché fruttifica sul legno di 2-3 anni. La pacciamatura mantiene umido questo apparato radicale superficiale.','Arbusto da bacche da giardino familiare molto diffuso in Svizzera, adatto ai bambini. Senza problemi fino a ~1400 m s.l.m. Nessun rischio radicale, piantabile vicino agli edifici.',NULL,'dopo il raccolto / inverno (diradare il legno vecchio)','f'),
('ribes_uva_crispa','en','Thorny – wear gloves when pruning. Susceptible to mildew: ensure an airy location and thinning cut, prefer mildew-resistant varieties. Berries edible (green to red/yellow).','Classic Swiss home-garden shrub, edible and safe. The thorns pose no toxic risk, but note the injury risk for small children. Up to ~1400 m.',NULL,'winter / after harvest (thin out for air circulation)','f'),
('ribes_uva_crispa','es','Espinoso – llevar guantes al podar. Sensible al oídio: asegurar una ubicación aireada y una poda de aclareo, preferir variedades resistentes al oídio. Bayas comestibles (de verdes a rojas/amarillas).','Arbusto clásico de los jardines domésticos suizos, comestible y seguro. Las espinas no suponen riesgo tóxico, pero tener en cuenta el riesgo de lesión para los niños pequeños. Hasta ~1400 m.',NULL,'invierno / después de la cosecha (aclarar para la circulación del aire)','f'),
('ribes_uva_crispa','fr','Épineux – porter des gants à la taille. Sensible à l''oïdium: assurer un emplacement aéré et une taille d''éclaircie, privilégier les variétés résistantes à l''oïdium. Baies comestibles (vertes à rouges/jaunes).','Arbuste classique des jardins familiaux suisses, comestible et sûr. Les épines ne présentent pas de risque toxique, mais attention au risque de blessure pour les jeunes enfants. Jusqu''à ~1400 m.',NULL,'hiver / après la récolte (éclaircir pour la circulation de l''air)','f'),
('ribes_uva_crispa','it','Spinoso – indossare guanti durante la potatura. Sensibile all''oidio: garantire una posizione arieggiata e un taglio di diradamento, preferire varietà resistenti all''oidio. Bacche commestibili (da verdi a rosse/gialle).','Arbusto classico dei giardini familiari svizzeri, commestibile e sicuro. Le spine non rappresentano un rischio tossico, ma attenzione al rischio di lesioni per i bambini piccoli. Fino a ~1400 m.',NULL,'inverno / dopo il raccolto (diradare per la circolazione dell''aria)','f'),
('ribes_x_nidigrolaria','en','Cross of blackcurrant × gooseberry – thornless, vigorous and robust against mildew and gall mite. Needs more space. Berries edible, in taste between currant and gooseberry.','Increasingly popular in Switzerland for its disease resistance and thornlessness – child-friendly. Allow for its space requirement. Up to ~1400 m.',NULL,'after harvest / winter (thin out old wood)','f'),
('ribes_x_nidigrolaria','es','Cruce de grosella negra × grosella espinosa – sin espinas, vigoroso y robusto frente al oídio y al ácaro de las yemas. Necesita más espacio. Bayas comestibles, de sabor entre la grosella y la grosella espinosa.','Cada vez más apreciado en Suiza por su resistencia a las enfermedades y su ausencia de espinas – apto para niños. Tener en cuenta su necesidad de espacio. Hasta ~1400 m.',NULL,'después de la cosecha / invierno (aclarar la madera vieja)','f'),
('ribes_x_nidigrolaria','fr','Croisement cassis × groseille à maquereau – sans épines, vigoureux et robuste face à l''oïdium et à l''ériophyide. Nécessite plus de place. Baies comestibles, au goût entre la groseille et la groseille à maquereau.','De plus en plus apprécié en Suisse pour sa résistance aux maladies et son absence d''épines – adapté aux enfants. Tenir compte du besoin de place. Jusqu''à ~1400 m.',NULL,'après la récolte / hiver (éclaircir le vieux bois)','f'),
('ribes_x_nidigrolaria','it','Incrocio ribes nero × uva spina – senza spine, vigoroso e robusto contro oidio ed eriofide. Necessita di più spazio. Bacche commestibili, di gusto intermedio tra ribes e uva spina.','Sempre più apprezzato in Svizzera per la resistenza alle malattie e l''assenza di spine – adatto ai bambini. Tenere conto del fabbisogno di spazio. Fino a ~1400 m.',NULL,'dopo il raccolto / inverno (diradare il legno vecchio)','f'),
('rosa_canina','en','Rose hips very rich in vitamins (vitamin C), edible – traditionally used for tea/jam. Bee forage (pollen). The prickles provide shelter for birds. Robust wild rose, hardly disease-prone. Caution: the seed hairs inside the rose hip are the classic "itching powder" (mechanical, non-toxic).','Native, one of the most common wild roses in Switzerland. Rose hips edible, ecologically valuable for birds and insects.',NULL,'Late winter or after flowering; tolerates pruning well','f'),
('rosa_canina','es','Escaramujos muy ricos en vitaminas (vitamina C), comestibles – tradicionalmente para infusión/mermelada. Planta melífera (polen). Las espinas ofrecen refugio a las aves. Rosa silvestre robusta, apenas susceptible a enfermedades. Atención: los pelos de las semillas dentro del escaramujo son los clásicos «polvos pica-pica» (mecánicos, no tóxicos).','Autóctona, una de las rosas silvestres más comunes de Suiza. Escaramujos comestibles, ecológicamente valiosos para aves e insectos.',NULL,'Final del invierno o tras la floración; tolera bien la poda','f'),
('rosa_canina','fr','Cynorhodons très riches en vitamines (vitamine C), comestibles – traditionnellement pour tisane/confiture. Plante mellifère (pollen). Les aiguillons offrent un abri aux oiseaux. Rosier sauvage robuste, peu sensible aux maladies. Attention : les poils des graines à l''intérieur du cynorhodon sont le classique « poil à gratter » (mécanique, non toxique).','Indigène, l''un des rosiers sauvages les plus fréquents de Suisse. Cynorhodons comestibles, écologiquement précieux pour les oiseaux et les insectes.',NULL,'Fin de l''hiver ou après la floraison ; supporte bien la taille','f'),
('rosa_canina','it','Cinorrodi molto ricchi di vitamine (vitamina C), commestibili – tradizionalmente per tisane/confettura. Pianta mellifera (polline). Le spine offrono riparo agli uccelli. Rosa selvatica robusta, poco soggetta a malattie. Attenzione: i peli dei semi all''interno del cinorrodo sono la classica «polvere prurito» (meccanica, non tossica).','Indigena, una delle rose selvatiche più diffuse in Svizzera. Cinorrodi commestibili, ecologicamente preziosi per uccelli e insetti.',NULL,'Fine inverno o dopo la fioritura; sopporta bene la potatura','f'),
('rubus_fruticosus_agg','en','Thornless cultivated varieties (e.g. ''Navaho'', ''Thornless Evergreen'') are easy on the hands. A sturdy trellis is needed because of the long canes. Fruits on two-year-old wood. Somewhat more frost-sensitive than raspberry – sheltered site, possibly winter protection of the canes.','In CH grows well up to ~1200 m; at higher elevations choose a frost-protected site. Edible and safe. Thornless varieties ideal for family gardens. Canes need a support trellis.',NULL,'after harvest remove the canes that have fruited; tie in young canes','f'),
('rubus_fruticosus_agg','es','Las variedades cultivadas sin espinas (p. ej. «Navaho», «Thornless Evergreen») son cómodas de manipular. Se necesita una espaldera robusta, ya que los tallos son largos. Fructifica en la madera de dos años. Algo más sensible a las heladas que la frambuesa – emplazamiento protegido, eventualmente protección invernal de los tallos.','En CH crece bien hasta ~1200 m; en altitud elegir un emplazamiento protegido de las heladas. Comestible y segura. Las variedades sin espinas son ideales para jardines familiares. Los tallos necesitan un enrejado de soporte.',NULL,'tras la cosecha eliminar los tallos que han fructificado; atar los tallos jóvenes','f'),
('rubus_fruticosus_agg','fr','Les variétés cultivées sans épines (p. ex. « Navaho », « Thornless Evergreen ») sont agréables à manipuler. Un solide espalier est nécessaire car les rameaux sont longs. Fructifie sur le bois de deux ans. Un peu plus sensible au gel que la framboise – emplacement abrité, éventuellement protection hivernale des rameaux.','En Suisse, pousse bien jusqu''à env. 1200 m ; en altitude, choisir un emplacement à l''abri du gel. Comestible et sûre. Variétés sans épines idéales pour les jardins familiaux. Les rameaux ont besoin d''un support de palissage.',NULL,'après la récolte, supprimer les rameaux ayant fructifié ; palisser les jeunes rameaux','f'),
('rubus_fruticosus_agg','it','Le varietà coltivate senza spine (p. es. «Navaho», «Thornless Evergreen») sono comode da maneggiare. È necessaria una robusta spalliera, poiché i tralci sono lunghi. Fruttifica sul legno di due anni. Un po'' più sensibile al gelo del lampone – posizione riparata, eventualmente protezione invernale dei tralci.','In Svizzera cresce bene fino a ca. 1200 m; in quota scegliere una posizione riparata dal gelo. Commestibile e sicura. Le varietà senza spine sono ideali per gli orti familiari. I tralci necessitano di un graticcio di sostegno.',NULL,'dopo la raccolta rimuovere i tralci che hanno fruttificato; legare i giovani tralci','f'),
('rubus_idaeus','en','Canes need a trellis/wire support. Suckers strongly – a root barrier or rhizome containment is recommended. Prefers acidic, humus-rich soil. Prune summer and autumn varieties differently.','In CH very popular up to medium elevations (~1600 m). Edible and safe; curb the suckering tendency in the home garden. Trellis required.',NULL,'Summer raspberry: after harvest remove the canes that have fruited; autumn raspberry: in winter cut down to ground level','f'),
('rubus_idaeus','es','Los tallos necesitan espaldera/emparrado de alambre. Emite muchos rebrotes de raíz – se recomienda una barrera antirrizoma o un confinamiento de los rizomas. Preferir un suelo ácido y rico en humus. Podar de forma distinta las variedades de verano y de otoño.','En CH muy apreciada hasta altitudes medias (~1600 m). Comestible y segura; contener la tendencia a rebrotar en el jardín doméstico. Espaldera necesaria.',NULL,'Frambueso de verano: tras la cosecha retirar los tallos que han fructificado; frambueso de otoño: en invierno cortar a ras de suelo','f'),
('rubus_idaeus','fr','Les rameaux ont besoin d''un espalier/treillis métallique. Émet fortement des drageons – barrière anti-rhizomes ou limitation des rhizomes recommandée. Préférer un sol acide et humifère. Tailler différemment les variétés d''été et d''automne.','En Suisse, très appréciée jusqu''aux altitudes moyennes (~1600 m). Comestible et sûre ; contenir la tendance aux drageons dans le jardin. Espalier nécessaire.',NULL,'Framboise d''été : après la récolte, retirer les rameaux ayant fructifié ; framboise d''automne : en hiver, couper au ras du sol','f'),
('rubus_idaeus','it','I tralci necessitano di spalliera/graticcio metallico. Emette molti polloni radicali – consigliata una barriera antirizoma o un contenimento dei rizomi. Preferire un terreno acido e ricco di humus. Potare diversamente le varietà estive e quelle autunnali.','In Svizzera molto apprezzata fino alle quote medie (~1600 m). Commestibile e sicura; contenere la tendenza ai polloni nell''orto domestico. Spalliera necessaria.',NULL,'Lampone estivo: dopo la raccolta togliere i tralci che hanno fruttificato; lampone autunnale: in inverno tagliare a livello del suolo','f'),
('salix_alba','en','Non-toxic (the bark contains salicin — a pharmacological aspirin precursor, harmless in garden amounts; do not consume deliberately). WARNING roots: strong, water-seeking shallow roots — drains, pipes and foundations at risk, minimum distance 12 m. Loves moist/wet sites and watercourse banks. Brittle branches — risk of wind breakage. Fast-growing, short-lived.','Native floodplain and riverbank tree of Switzerland up to ~1500 m, valuable for renaturation and as an early bee forage. Because of root pressure and brittle wood, not near buildings/paths. Ideal by watercourses, not in the small garden.',NULL,'Winter to early spring; very pruning-tolerant (pollarding)','f'),
('salix_alba','es','No tóxico (la corteza contiene salicina — precursor farmacológico de la aspirina, inofensivo en cantidades de jardín; no consumir deliberadamente). ADVERTENCIA raíces: raíces superficiales fuertes y ávidas de agua — drenajes, tuberías y cimientos en peligro, distancia mínima 12 m. Le gustan los emplazamientos húmedos/mojados y las orillas de los cursos de agua. Ramas quebradizas — riesgo de rotura por viento. De crecimiento rápido, vida corta.','Árbol autóctono de las zonas aluviales y riberas de Suiza hasta ~1500 m, valioso para la renaturalización y como temprana planta melífera. Debido a la presión radicular y la madera quebradiza, no cerca de edificios/caminos. Ideal junto a cursos de agua, no en el jardín pequeño.',NULL,'Invierno hasta principios de primavera; muy tolerante a la poda (poda en trasmocho)','f'),
('salix_alba','fr','Non toxique (l''écorce contient de la salicine — précurseur pharmacologique de l''aspirine, sans danger aux quantités de jardin ; ne pas consommer délibérément). AVERTISSEMENT racines : racines traçantes puissantes et avides d''eau — drainages, conduites et fondations menacés, distance minimale 12 m. Aime les emplacements humides/mouillés et les berges. Branches cassantes — risque de bris par le vent. Croissance rapide, courte durée de vie.','Arbre indigène des zones alluviales et des berges de Suisse jusqu''à ~1500 m, précieux pour la renaturation et comme plante mellifère précoce. En raison de la pression racinaire et du bois cassant, à éviter près des bâtiments/chemins. Idéal au bord des eaux, pas dans le petit jardin.',NULL,'Hiver à début du printemps ; supporte très bien la taille (taille en têtard)','f'),
('salix_alba','it','Non tossico (la corteccia contiene salicina — precursore farmacologico dell''aspirina, innocuo nelle quantità da giardino; non consumare deliberatamente). AVVERTENZA radici: radici superficiali forti e avide d''acqua — drenaggi, tubature e fondamenta a rischio, distanza minima 12 m. Ama i luoghi umidi/bagnati e le sponde dei corsi d''acqua. Rami fragili — pericolo di rottura da vento. Crescita rapida, breve durata di vita.','Albero indigeno delle zone golenali e ripariali della Svizzera fino a ~1500 m, prezioso per la rinaturazione e come precoce pianta mellifera. A causa della pressione radicale e del legno fragile, da evitare vicino a edifici/sentieri. Ideale lungo i corsi d''acqua, non nel piccolo giardino.',NULL,'Inverno fino a inizio primavera; sopporta molto bene la potatura (capitozzatura a salice)','f'),
('salix_caprea','en','One of the MOST IMPORTANT early bee forage plants (yellow catkins, pollen + nectar in March, dioecious - male specimens more valuable for pollen). Water-seeking roots - keep distance from drains/pipes (root risk medium). Fast-growing.','Native, ecologically one of the most valuable early-flowering insect forage plants in Switzerland. Dioecious. Moisture-loving - not for dry sites.',NULL,'after flowering (March/April) or in winter; very pruning-tolerant, pollarding possible','f'),
('salix_caprea','es','Una de las MÁS IMPORTANTES plantas melíferas tempranas (amentos amarillos, polen + néctar en marzo, dioica - los ejemplares masculinos son más valiosos por el polen). Raíces ávidas de agua - mantener distancia de drenajes/tuberías (riesgo radicular medio). De crecimiento rápido.','Autóctona, ecológicamente una de las plantas nutricias tempranas más valiosas para los insectos en Suiza. Dioica. Amante de la humedad - no apta para emplazamientos secos.',NULL,'tras la floración (marzo/abril) o en invierno; muy tolerante a la poda, posible la poda en trasmocho','f'),
('salix_caprea','fr','L''une des plantes mellifères précoces les PLUS IMPORTANTES (chatons jaunes, pollen + nectar en mars, dioïque - les sujets mâles sont plus précieux pour le pollen). Racines avides d''eau - garder une distance avec les drainages/conduites (risque racinaire moyen). Croissance rapide.','Indigène, écologiquement l''une des plantes nourricières précoces les plus précieuses pour les insectes en Suisse. Dioïque. Aime l''humidité - pas pour les emplacements secs.',NULL,'après la floraison (mars/avril) ou en hiver ; supporte très bien la taille, taille en têtard possible','f'),
('salix_caprea','it','Una delle più IMPORTANTI piante mellifere precoci (amenti gialli, polline + nettare a marzo, dioica - gli esemplari maschili sono più preziosi per il polline). Radici avide d''acqua - mantenere la distanza da drenaggi/condutture (rischio radicale medio). Crescita rapida.','Indigena, ecologicamente una delle più preziose piante nutrici precoci per gli insetti in Svizzera. Dioica. Ama l''umidità - non adatta a luoghi aridi.',NULL,'dopo la fioritura (marzo/aprile) o in inverno; sopporta molto bene la potatura, possibile la capitozzatura a salice','f'),
('sambucus_nigra','en','Very vigorous and undemanding, loves nitrogen-rich, fresh soils (nutrient indicator). Use the berries ONLY cooked/heated (juice, jelly, syrup) – slightly toxic raw due to sambunigrin. Flowers edible (elderflower fritters/syrup). Child safety: raw-toxic berries → child_pet_safe=false.','Native wild shrub throughout CH up to 1500 m, common along waysides, near farmyards and in hedges (nitrogen indicator). Important bird forage shrub and bee forage. Traditionally elderflower syrup and cooked elderberry juice.','Leaves, bark, unripe berries and the seeds of ripe berries contain the cyanogenic glycoside sambunigrin – eaten raw: nausea, vomiting, diarrhea (especially in children and with unripe/raw berries). Destroyed by heating above approx. 76 °C → harmless once cooked','Winter (February) to early spring; tolerates hard pruning','f'),
('sambucus_nigra','es','Muy vigoroso y poco exigente, ama los suelos ricos en nitrógeno, frescos (indicador de nutrientes). Usar las bayas SOLO cocidas/calentadas (zumo, jalea, sirope) – ligeramente tóxicas crudas por la sambunigrina. Flores comestibles (buñuelos de saúco/sirope). Seguridad infantil: bayas tóxicas crudas → child_pet_safe=false.','Arbusto silvestre autóctono en toda CH hasta 1500 m, frecuente en los bordes de los caminos, cerca de granjas y en setos (indicador de nitrógeno). Importante arbusto nutricio para las aves y planta melífera. Tradicionalmente sirope de flores de saúco y zumo de saúco cocido.','Las hojas, la corteza, las bayas no maduras y las semillas de las bayas maduras contienen el glucósido cianogénico sambunigrina – consumidas crudas: náuseas, vómitos, diarrea (sobre todo en niños y con bayas no maduras/crudas). Se destruye al calentar por encima de unos 76 °C → inofensivo una vez cocido','Invierno (febrero) hasta principios de primavera; tolera una poda severa','f'),
('sambucus_nigra','fr','Très vigoureux et peu exigeant, aime les sols riches en azote, frais (indicateur de nutriments). Utiliser les baies UNIQUEMENT cuites/chauffées (jus, gelée, sirop) – légèrement toxiques crues à cause de la sambunigrine. Fleurs comestibles (beignets de sureau/sirop). Sécurité enfants : baies toxiques crues → child_pet_safe=false.','Arbuste sauvage indigène dans toute la CH jusqu''à 1500 m, fréquent en bordure de chemins, à proximité des fermes et dans les haies (indicateur d''azote). Important arbuste nourricier pour les oiseaux et plante mellifère. Traditionnellement sirop de fleurs de sureau et jus de sureau cuit.','Les feuilles, l''écorce, les baies non mûres et les graines des baies mûres contiennent le glycoside cyanogène sambunigrine – consommées crues : nausées, vomissements, diarrhée (surtout chez les enfants et avec des baies non mûres/crues). Détruit par chauffage au-dessus d''env. 76 °C → inoffensif une fois cuit','Hiver (février) à début du printemps ; supporte une taille sévère','f'),
('sambucus_nigra','it','Molto vigoroso e poco esigente, ama i suoli ricchi di azoto, freschi (indicatore di nutrienti). Usare le bacche SOLO cotte/riscaldate (succo, gelatina, sciroppo) – leggermente tossiche crude per via della sambunigrina. Fiori commestibili (frittelle di sambuco/sciroppo). Sicurezza bambini: bacche tossiche crude → child_pet_safe=false.','Arbusto selvatico indigeno in tutta la CH fino a 1500 m, frequente ai bordi dei sentieri, nei pressi delle fattorie e nelle siepi (indicatore di azoto). Importante arbusto nutrice per gli uccelli e pianta mellifera. Tradizionalmente sciroppo di fiori di sambuco e succo di sambuco cotto.','Foglie, corteccia, bacche acerbe e i semi delle bacche mature contengono il glicoside cianogenico sambunigrina – consumate crude: nausea, vomito, diarrea (soprattutto nei bambini e con bacche acerbe/crude). Distrutto dal riscaldamento oltre ca. 76 °C → innocuo una volta cotto','Inverno (febbraio) fino a inizio primavera; sopporta una potatura energica','f'),
('sorbus_aucuparia','en','Pioneer species, extremely frost-hardy up to high elevations. Very valuable as a bird forage shrub (berries). Raw, the berries are only slightly irritating - no serious danger, but do not eat raw.','Native, classic mountain tree up to 2400 m. One of the most important bird forage plants in Switzerland. Fire blight host.','raw berries contain parasorbic acid (gastrointestinal irritation when raw); broken down by cooking/frost, then processable; the seeds contain cyanogenic glycosides','in winter (leafless) if needed; Sorbus tolerates pruning poorly - sparingly','f'),
('sorbus_aucuparia','es','Especie pionera, extremadamente resistente a las heladas hasta altitudes elevadas. Muy valiosa como arbusto nutricio para las aves (bayas). Crudas, las bayas solo son ligeramente irritantes - sin peligro grave, pero no consumir crudas.','Autóctona, árbol de montaña clásico hasta 2400 m. Una de las plantas nutricias para aves más importantes de Suiza. Hospedador del fuego bacteriano.','las bayas crudas contienen ácido parasórbico (irritación gastrointestinal en crudo); se degrada con la cocción/la helada, entonces procesable; las semillas contienen glucósidos cianogénicos','en invierno (sin hojas) si es necesario; el Sorbus tolera mal la poda - con moderación','f'),
('sorbus_aucuparia','fr','Essence pionnière, extrêmement résistante au gel jusqu''aux hautes altitudes. Très précieuse comme arbuste nourricier pour les oiseaux (baies). Crues, les baies ne sont que légèrement irritantes - pas de danger sérieux, mais ne pas consommer crues.','Indigène, arbre de montagne classique jusqu''à 2400 m. L''une des plantes nourricières pour oiseaux les plus importantes de Suisse. Hôte du feu bactérien.','les baies crues contiennent de l''acide parasorbique (irritation gastro-intestinale crues) ; dégradé par la cuisson/le gel, alors transformable ; les pépins contiennent des glycosides cyanogènes','en hiver (sans feuilles) si nécessaire ; Sorbus supporte mal la taille - avec parcimonie','f'),
('sorbus_aucuparia','it','Specie pioniera, estremamente resistente al gelo fino alle alte quote. Molto preziosa come arbusto nutrice per gli uccelli (bacche). Crude, le bacche sono solo leggermente irritanti - nessun pericolo grave, ma non consumare crude.','Indigena, classico albero di montagna fino a 2400 m. Una delle più importanti piante nutrici per uccelli della Svizzera. Ospite del colpo di fuoco batterico.','le bacche crude contengono acido parasorbico (irritazione gastrointestinale da crude); degradato dalla cottura/dal gelo, poi lavorabile; i semi contengono glicosidi cianogenici','in inverno (senza foglie) se necessario; il Sorbus sopporta male la potatura - con parsimonia','f'),
('sorbus_domestica','en','Warmth-loving, slow-growing, very long-lived characterful tree. Drought- and lime-tolerant. Fruits (service tree fruits) only edible when bletted/over-ripe, traditionally for cider/spirits. Has become rare, ecologically and genetically valuable.','In CH rare and worthy of protection, warmth-loving – warm, lime-rich sites in the Plateau/Jura up to about 900 m. Rare native tree species worthy of promotion (silviculturally/ecologically valuable).','Fruits only edible when bletted/over-ripe (raw hard and very tannin-rich/astringent, but not toxic)','Winter (dormancy), very little pruning needed','f'),
('sorbus_domestica','es','Árbol singular termófilo, de crecimiento lento, muy longevo. Tolerante a la sequía y a la cal. Frutos (serbas) comestibles solo cuando están pasados/sobremaduros, tradicionalmente para sidra/aguardiente. Se ha vuelto raro, ecológica y genéticamente valioso.','En CH raro y digno de protección, termófilo – emplazamientos cálidos y calcáreos de la Meseta/Jura hasta aprox. 900 m. Especie arbórea autóctona rara, digna de fomento (valiosa desde el punto de vista forestal/ecológico).','Frutos comestibles solo cuando están pasados/sobremaduros (crudos duros y muy ricos en taninos/astringentes, pero no tóxicos)','Invierno (reposo vegetativo), apenas necesita poda','f'),
('sorbus_domestica','fr','Arbre de caractère thermophile, à croissance lente, très longévif. Tolérant à la sécheresse et au calcaire. Fruits (cormes) comestibles seulement blets/surmûris, traditionnellement pour cidre/eau-de-vie. Devenu rare, écologiquement et génétiquement précieux.','En CH rare et digne de protection, thermophile – emplacements chauds et calcaires du Plateau/Jura jusqu''à env. 900 m. Essence indigène rare digne d''être encouragée (précieuse sur le plan forestier/écologique).','Fruits comestibles seulement blets/surmûris (crus durs et très riches en tanins/astringents, mais non toxiques)','Hiver (repos végétatif), très peu de taille nécessaire','f'),
('sorbus_domestica','it','Albero caratteristico termofilo, a crescita lenta, molto longevo. Tollerante alla siccità e al calcare. Frutti (sorbe) commestibili solo quando ammezziti/troppo maturi, tradizionalmente per sidro/acquavite. Divenuto raro, ecologicamente e geneticamente prezioso.','In CH raro e degno di protezione, termofilo – posizioni calde e calcaree dell''Altopiano/Giura fino a ca. 900 m. Specie arborea indigena rara, degna di promozione (preziosa dal punto di vista forestale/ecologico).','Frutti commestibili solo ammezziti/troppo maturi (crudi duri e molto ricchi di tannini/astringenti, ma non tossici)','Inverno (riposo vegetativo), serve pochissima potatura','f'),
('sorbus_torminalis','en','Warmth-loving, slow-growing, long-lived noble broadleaf species with very valuable wood. Drought- and lime-tolerant. Light-demanding within the stand. Fruits (wild service tree fruits) edible when over-ripe, traditionally for spirits. Beautiful autumn colouring.','Native, rare noble broadleaf species of warm, lime-rich sites in the Plateau/Jura up to about 1000 m. Worthy of promotion, ecologically valuable. ''Swiss pear tree'' as a folk name; prized furniture wood.','Fruits only edible when over-ripe/bletted (raw very tannin-rich/astringent, not toxic)','Winter (dormancy), little pruning','f'),
('sorbus_torminalis','es','Frondosa noble termófila, de crecimiento lento, longeva, con madera muy valiosa. Tolerante a la sequía y a la cal. Exigente en luz dentro de la masa forestal. Frutos (mostajos) comestibles sobremaduros, tradicionalmente para aguardiente. Bonita coloración otoñal.','Frondosa noble autóctona y rara de los emplazamientos cálidos y calcáreos de la Meseta/Jura hasta aprox. 1000 m. Digna de fomento, ecológicamente valiosa. «Peral suizo» como nombre popular; apreciada madera de ebanistería.','Frutos comestibles solo sobremaduros/pasados (crudos muy ricos en taninos/astringentes, no tóxicos)','Invierno (reposo vegetativo), poca poda','f'),
('sorbus_torminalis','fr','Essence feuillue noble thermophile, à croissance lente, longévive, au bois très précieux. Tolérante à la sécheresse et au calcaire. Exigeante en lumière dans le peuplement. Fruits (alisiers) comestibles surmûris, traditionnellement pour eau-de-vie. Belle coloration automnale.','Essence feuillue noble indigène et rare des emplacements chauds et calcaires du Plateau/Jura jusqu''à env. 1000 m. Digne d''être encouragée, écologiquement précieuse. « Poirier suisse » comme nom populaire ; bois d''ébénisterie apprécié.','Fruits comestibles seulement surmûris/blets (crus très riches en tanins/astringents, non toxiques)','Hiver (repos végétatif), peu de taille','f'),
('sorbus_torminalis','it','Pregiata latifoglia nobile termofila, a crescita lenta, longeva, dal legno molto pregiato. Tollerante alla siccità e al calcare. Esigente di luce nel popolamento. Frutti (sorbe torminali) commestibili se troppo maturi, tradizionalmente per acquavite. Bella colorazione autunnale.','Latifoglia nobile indigena e rara delle posizioni calde e calcaree dell''Altopiano/Giura fino a ca. 1000 m. Degna di promozione, ecologicamente preziosa. «Pero svizzero» come nome popolare; apprezzato legname da mobili.','Frutti commestibili solo troppo maturi/ammezziti (crudi molto ricchi di tannini/astringenti, non tossici)','Inverno (riposo vegetativo), poca potatura','f'),
('taxus_baccata','en','DEADLY POISONOUS: taxine alkaloids in needles and seeds — a few needles/seeds can cause cardiac arrest, no antidote. Highest toxicity level (+++). Never leave pruning material accessible to animals. The red aril itself is non-toxic, but the seed inside it is deadly.','Native, protected. The most common deadly poisonous hedge plant — critical for children, horses, cattle. If poisoning is suspected, call Tox Info Suisse 145 immediately.','all parts except the red aril; needles, seeds, bark, wood (taxine alkaloids)','April-September (at any time, tolerates cutting back into old wood)','f'),
('taxus_baccata','es','MORTALMENTE TÓXICO: alcaloides de taxina en las acículas y las semillas — pocas acículas/semillas pueden provocar un paro cardíaco, sin antídoto. Máximo nivel de toxicidad (+++). No dejar nunca los restos de poda al alcance de los animales. El arilo rojo en sí no es tóxico, pero la semilla que contiene es mortal.','Autóctono, protegido. La planta de seto mortalmente tóxica más frecuente — crítica para niños, caballos, vacuno. En caso de sospecha, llamar de inmediato a Tox Info Suisse 145.','todas las partes excepto el arilo rojo; acículas, semillas, corteza, madera (alcaloides de taxina)','abril-septiembre (en cualquier momento, tolera la poda hasta la madera vieja)','f'),
('taxus_baccata','fr','MORTELLEMENT TOXIQUE : alcaloïdes de type taxine dans les aiguilles et les graines — quelques aiguilles/graines peuvent provoquer un arrêt cardiaque, pas d''antidote. Niveau de toxicité maximal (+++). Ne jamais laisser les déchets de taille accessibles aux animaux. L''arille rouge lui-même est non toxique, mais la graine qu''il contient est mortelle.','Indigène, protégé. Plante de haie mortellement toxique la plus fréquente — critique pour les enfants, les chevaux, les bovins. En cas de suspicion, appeler immédiatement Tox Info Suisse 145.','toutes les parties sauf l''arille rouge ; aiguilles, graines, écorce, bois (alcaloïdes de type taxine)','avril-septembre (à tout moment, supporte la taille jusque dans le vieux bois)','f'),
('taxus_baccata','it','MORTALMENTE TOSSICO: alcaloidi tassinici negli aghi e nei semi — pochi aghi/semi possono provocare un arresto cardiaco, nessun antidoto. Massimo livello di tossicità (+++). Non lasciare mai i residui di potatura accessibili agli animali. L''arillo rosso è di per sé non tossico, ma il seme al suo interno è mortale.','Indigeno, protetto. La pianta da siepe mortalmente tossica più frequente — critica per bambini, cavalli, bovini. In caso di sospetto chiamare subito Tox Info Suisse 145.','tutte le parti tranne l''arillo rosso; aghi, semi, corteccia, legno (alcaloidi tassinici)','aprile-settembre (in qualsiasi momento, sopporta la potatura fino nel legno vecchio)','f'),
('thuja_occidentalis','en','Highly toxic: thujone — vomiting, convulsions, in severe cases coma, liver/kidney damage (tox.ch). Skin-irritating when cut (gloves). Shallow-rooted, avoid waterlogging, high water demand. Browns in drought.','Very common privacy hedge, ecologically poor (no food for insects/birds). Keep cuttings away from children/animals. Tox Info Suisse 145.','all parts, especially shoot tips and cones (thujone, essential oils)','April-August (not into old wood — does not regrow)','f'),
('thuja_occidentalis','es','Muy tóxico: tuyona — vómitos, convulsiones, en casos graves coma, daños hepáticos/renales (tox.ch). Irritante para la piel al podar (guantes). Raíces superficiales, evitar el encharcamiento, alta demanda de agua. Se vuelve marrón con la sequía.','Seto de privacidad muy común, ecológicamente pobre (sin alimento para insectos/aves). Evitar el contacto de los restos de poda con niños/animales. Tox Info Suisse 145.','todas las partes, sobre todo las puntas de los brotes y los conos (tuyona, aceites esenciales)','abril-agosto (no en la madera vieja — no rebrota)','f'),
('thuja_occidentalis','fr','Fortement toxique : thuyone — vomissements, convulsions, dans les cas graves coma, lésions hépatiques/rénales (tox.ch). Irritant pour la peau lors de la taille (gants). Enracinement superficiel, éviter l''eau stagnante, besoin en eau élevé. Brunit en cas de sécheresse.','Haie brise-vue très répandue, pauvre sur le plan écologique (aucune nourriture pour insectes/oiseaux). Éviter le contact des résidus de taille avec enfants/animaux. Tox Info Suisse 145.','toutes les parties, surtout les pousses terminales et les cônes (thuyone, huiles essentielles)','avril-août (pas dans le vieux bois — ne repousse pas)','f'),
('thuja_occidentalis','it','Fortemente tossico: tujone — vomito, convulsioni, nei casi gravi coma, danni epatici/renali (tox.ch). Irritante per la pelle durante la potatura (guanti). Radici superficiali, evitare i ristagni d''acqua, elevato fabbisogno idrico. Imbrunisce in caso di siccità.','Siepe frangivista molto diffusa, ecologicamente povera (nessun nutrimento per insetti/uccelli). Evitare il contatto del materiale di taglio con bambini/animali. Tox Info Suisse 145.','tutte le parti, soprattutto gli apici dei germogli e i coni (tujone, oli essenziali)','aprile-agosto (non sul legno vecchio — non ricaccia)','f'),
('tilia_cordata','en','Hardier and somewhat smaller than the large-leaved lime, flowers 2-3 weeks later. Very valuable late nectar source for bees. Urban-climate tolerant. Long-lived.','More climate-resilient lime species for Switzerland, up to ~1200 m. Frequently planted as an avenue and park tree. Honeydew makes surfaces under the crown sticky.',NULL,'late winter (February) or after flowering; tolerates pruning well','f'),
('tilia_cordata','es','Más resistente y algo más pequeño que el tilo de hoja grande, florece 2-3 semanas más tarde. Fuente de néctar tardía muy valiosa para las abejas. Tolera el clima urbano. Longevo.','Especie de tilo más resiliente al clima para Suiza, hasta ~1200 m. Frecuente como árbol de avenida y de parque. La melaza pega los pavimentos bajo la copa.',NULL,'finales de invierno (febrero) o tras la floración; tolera bien la poda','f'),
('tilia_cordata','fr','Plus rustique et un peu plus petit que le tilleul à grandes feuilles, fleurit 2-3 semaines plus tard. Source de nectar tardive très précieuse pour les abeilles. Tolère le climat urbain. Longévité élevée.','Espèce de tilleul plus résiliente au climat pour la Suisse, jusqu''à ~1200 m. Souvent planté en allée et dans les parcs. Le miellat colle les revêtements sous la couronne.',NULL,'fin d''hiver (février) ou après la floraison ; supporte bien la taille','f'),
('tilia_cordata','it','Più rustico e un po'' più piccolo del tiglio nostrano, fiorisce 2-3 settimane più tardi. Fonte di nettare tardiva molto preziosa per le api. Tollera il clima urbano. Longevo.','Specie di tiglio più resiliente al clima per la Svizzera, fino a ~1200 m. Spesso usato come albero da viale e da parco. La melata appiccica le pavimentazioni sotto la chioma.',NULL,'fine inverno (febbraio) o dopo la fioritura; tollera bene la potatura','f'),
('tilia_platyphyllos','en','Classic avenue and farmyard tree, very long-lived (200+ years). Flowers earlier than the small-leaved lime. Valuable nectar source for bees. Large space requirement, not for small gardens.','In Switzerland a traditional village-lime tree, found up to ~1000 m. Due to its size, keep a minimum distance from buildings.',NULL,'late winter (February) or after flowering; tolerates hard pruning','f'),
('tilia_platyphyllos','es','Árbol de avenida y de patio clásico, muy longevo (200+ años). Florece antes que el tilo de hoja pequeña. Valiosa fuente de néctar para las abejas. Gran necesidad de espacio, no apto para jardines pequeños.','En Suiza, árbol tradicional del tilo de pueblo, presente hasta ~1000 m. Por su tamaño, mantener una distancia mínima a los edificios.',NULL,'finales de invierno (febrero) o tras la floración; tolera una poda fuerte','f'),
('tilia_platyphyllos','fr','Arbre d''allée et de cour classique, très longévif (200+ ans). Fleurit plus tôt que le tilleul à petites feuilles. Précieuse source de nectar pour les abeilles. Grand besoin d''espace, pas pour les petits jardins.','En Suisse, arbre traditionnel du tilleul de village, répandu jusqu''à ~1000 m. En raison de sa taille, respecter une distance minimale aux bâtiments.',NULL,'fin d''hiver (février) ou après la floraison ; supporte une taille sévère','f'),
('tilia_platyphyllos','it','Albero da viale e da cortile classico, molto longevo (200+ anni). Fiorisce prima del tiglio selvatico. Preziosa fonte di nettare per le api. Grande ingombro, non adatto ai piccoli giardini.','In Svizzera, albero tradizionale del tiglio di villaggio, diffuso fino a ~1000 m. Per via delle dimensioni, mantenere una distanza minima dagli edifici.',NULL,'fine inverno (febbraio) o dopo la fioritura; tollera una potatura energica','f'),
('tsuga_heterophylla','en','Not to be confused with toxic hemlock (Conium / ''poison hemlock'') — western hemlock is non-toxic. Very shade-tolerant, needs steady moisture, suffers in drought/heat. Shallow-rooted.','Rarely planted guest tree species in parks/trial plots, prefers cool, humid-air sites. Due to drought sensitivity, only partly climate-suitable in the Swiss Plateau.',NULL,'late summer; tolerates pruning well','f'),
('tsuga_heterophylla','es','No confundir con la cicuta tóxica (Conium / ''poison hemlock'') — la tsuga occidental no es tóxica. Muy tolerante a la sombra, necesita humedad constante, sufre con la sequía/el calor. Raíces superficiales.','Especie arbórea foránea raramente plantada, en parques/parcelas de ensayo, prefiere lugares frescos y de aire húmedo. Por su sensibilidad a la sequía, solo parcialmente apta al clima de la Meseta suiza.',NULL,'finales de verano; tolera bien la poda','f'),
('tsuga_heterophylla','fr','Ne pas confondre avec la ciguë toxique (Conium / ''poison hemlock'') — la pruche de l''Ouest est non toxique. Très tolérante à l''ombre, exige une humidité régulière, souffre de la sécheresse/chaleur. Enracinement superficiel.','Espèce exotique rarement plantée, en parcs/parcelles d''essai, préfère les situations fraîches et à air humide. En raison de sa sensibilité à la sécheresse, n''est que partiellement adaptée au climat du Plateau suisse.',NULL,'fin d''été ; supporte bien la taille','f'),
('tsuga_heterophylla','it','Da non confondere con la cicuta velenosa (Conium / ''poison hemlock'') — la tsuga occidentale non è tossica. Molto tollerante all''ombra, richiede umidità costante, soffre in caso di siccità/caldo. Radici superficiali.','Specie ospite raramente piantata, in parchi/parcelle sperimentali, predilige posizioni fresche e con aria umida. Per la sua sensibilità alla siccità, solo parzialmente idonea al clima dell''Altopiano svizzero.',NULL,'fine estate; tollera bene la potatura','f'),
('vaccinium_corymbosum','en','Strictly acid-soil plant (pH 4-5.5) — rhododendron/ericaceous soil, no lime, no hard tap water (water with rainwater). Keep shallow roots evenly moist, mulch. Self-fertile, but a second variety markedly increases yield.','In Switzerland succeeds only with acidic substrate — the most common mistake is too high a soil pH. Up to ~1200 m. Edible and safe. Drosophila suzukii is a widespread harvest problem in Switzerland.',NULL,'late winter (thin out old wood)','f'),
('vaccinium_corymbosum','es','Planta estrictamente acidófila (pH 4-5,5) — tierra de rododendro/de brezo, sin cal, sin agua del grifo dura (regar con agua de lluvia). Raíces superficiales a mantener uniformemente húmedas, acolchar. Autofértil, pero una segunda variedad aumenta notablemente el rendimiento.','En Suiza solo prospera con sustrato ácido — el error más frecuente es un pH del suelo demasiado alto. Hasta ~1200 m. Comestible y seguro. Drosophila suzukii es un problema de cosecha extendido en Suiza.',NULL,'finales de invierno (aclarar la madera vieja)','f'),
('vaccinium_corymbosum','fr','Plante strictement acidophile (pH 4-5,5) — terre de rhododendron/de bruyère, sans calcaire, sans eau du robinet dure (arroser à l''eau de pluie). Enracinement superficiel à maintenir uniformément humide, pailler. Autofertile, mais une seconde variété augmente nettement le rendement.','En Suisse, ne réussit qu''avec un substrat acide — l''erreur la plus fréquente est un pH du sol trop élevé. Jusqu''à ~1200 m. Comestible et sûr. Drosophila suzukii est un problème de récolte répandu en Suisse.',NULL,'fin d''hiver (éclaircir le vieux bois)','f'),
('vaccinium_corymbosum','it','Pianta rigorosamente acidofila (pH 4-5,5) — terra per rododendri/da brughiera, niente calcare, niente acqua di rubinetto dura (irrigare con acqua piovana). Radici superficiali da mantenere uniformemente umide, pacciamare. Autofertile, ma una seconda varietà aumenta nettamente la resa.','In Svizzera riesce solo con substrato acido — l''errore più frequente è un pH del suolo troppo alto. Fino a ~1200 m. Commestibile e sicuro. Drosophila suzukii è un problema di raccolta diffuso in Svizzera.',NULL,'fine inverno (diradare il legno vecchio)','f'),
('viburnum_lantana','en','Lime-loving, drought-tolerant — good heat shrub for dry sites. Bird-food shrub. Felty-hairy leaves (hence ''wayfaring/woolly''). Slightly toxic — not a serious hazard, but do not eat the berries.','Native (heat-loving, calcareous soils of the Jura/Valais), drought-resistant — climate-adapted.','unripe fruits and bark slightly toxic (gastrointestinal upset if raw unripe berries are eaten); ripe black berries little problematic but inedible','after flowering; tolerates rejuvenation pruning well','f'),
('viburnum_lantana','es','Calcícola, resistente a la sequía — buen arbusto de calor para emplazamientos secos. Arbusto que alimenta a las aves. Hojas afieltradas-pubescentes (de ahí ''lanudo''). Ligeramente tóxico — no es un peligro grave, pero no consumir las bayas.','Autóctono (termófilo, suelos calcáreos del Jura/Valais), resistente a la sequía — adaptado al clima.','frutos inmaduros y corteza ligeramente tóxicos (molestias gastrointestinales si se consumen bayas crudas inmaduras); las bayas negras maduras son poco problemáticas pero incomestibles','tras la floración; tolera bien la poda de rejuvenecimiento','f'),
('viburnum_lantana','fr','Calcicole, résistant à la sécheresse — bon arbuste de chaleur pour les stations sèches. Arbuste nourricier pour les oiseaux. Feuilles feutrées-pubescentes (d''où ''cotonneuse''). Légèrement toxique — pas de danger grave, mais ne pas consommer les baies.','Indigène (thermophile, sols calcaires du Jura/Valais), résistant à la sécheresse — adapté au climat.','fruits non mûrs et écorce légèrement toxiques (troubles gastro-intestinaux en cas de consommation de baies crues non mûres) ; les baies noires mûres sont peu problématiques mais immangeables','après la floraison ; supporte bien la taille de rajeunissement','f'),
('viburnum_lantana','it','Calcicola, resistente alla siccità — buon arbusto da calore per stazioni aride. Arbusto da frutto per gli uccelli. Foglie feltrose-pubescenti (da cui ''lanoso''). Leggermente tossico — non un pericolo grave, ma non consumare le bacche.','Autoctono (termofilo, suoli calcarei del Giura/Vallese), resistente alla siccità — adatto al clima.','frutti acerbi e corteccia leggermente tossici (disturbi gastrointestinali se si consumano bacche crude acerbe); le bacche nere mature sono poco problematiche ma immangiabili','dopo la fioritura; tollera bene la potatura di ringiovanimento','f')
